    const pocketsCount = Array.isArray(impFin.pockets) ? impFin.pockets.length : 0;
    const subsCount = Array.isArray(impFin.subscriptions) ? impFin.subscriptions.length : 0;
    const assetsCount = Array.isArray(impFin.fixedAssets) ? impFin.fixedAssets.length : 0;
