document.getElementById('btn-done-sync-rates')?.addEventListener('click', closeSyncRatesModal);

document.getElementById('btn-sync-rates')?.addEventListener('click', async (e) => {
    const btn = e.currentTarget;
    const originalText = btn.innerHTML;
    btn.innerHTML = `<span style="display:inline-flex; align-items:center; justify-content:center; gap:6px;"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12a9 9 0 0 0-9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/><path d="M3 12a9 9 0 0 0 9 9 9.75 9.75 0 0 0 6.74-2.74L21 16"/><path d="M16 16h5v5"/></svg><span>Consultando...</span></span>`;
    btn.disabled = true;

    try {
        if (!navigator.onLine) throw new Error('No hay conexión a internet.');

        // Consulta en solo lectura a APIs publicas autorizadas por el Cortafuegos Local-First
        let usdCop = 0;
        let eurCop = 0;

        const fetchRateJson = async (url, timeoutMs = 8000) => {
            const ctrl = typeof AbortController !== 'undefined' ? new AbortController() : null;
            const tId = ctrl ? setTimeout(() => ctrl.abort(), timeoutMs) : null;
            try {
                const resp = await fetch(url, ctrl ? { signal: ctrl.signal } : {});
                if (!resp.ok) return null;
                return await resp.json();
            } catch {
                return null;
            } finally {
                if (tId) clearTimeout(tId);
            }
        };

        const trmArr = await fetchRateJson('https://www.datos.gov.co/resource/32sa-8pi3.json?$limit=1&$order=vigenciadesde%20DESC');
        const trmVal = parseFloat(trmArr?.[0]?.valor);
        if (Number.isFinite(trmVal) && trmVal > 500 && trmVal < 50000) usdCop = trmVal;

        if (!usdCop) {
            const dataUsd = await fetchRateJson('https://open.er-api.com/v6/latest/USD');
            const copVal = Number(dataUsd?.rates?.COP);
            if (Number.isFinite(copVal) && copVal > 500 && copVal < 50000) usdCop = copVal;
        }
        if (!usdCop) throw new Error('Error consultando tasa USD.');

        const dataEur = await fetchRateJson('https://open.er-api.com/v6/latest/EUR');
        const eurDirect = Number(dataEur?.rates?.COP);
        if (Number.isFinite(eurDirect) && eurDirect > 500 && eurDirect < 60000) {
            eurCop = eurDirect;
        }

        if (!eurCop && usdCop > 0) {
            const dataFrank = await fetchRateJson('https://api.frankfurter.app/latest?from=EUR&to=USD');
            const eurUsd = Number(dataFrank?.rates?.USD);
            if (Number.isFinite(eurUsd) && eurUsd > 0.5 && eurUsd < 3) {
                eurCop = round2(usdCop * eurUsd);
            }
        }

        if (usdCop > 0 && eurCop > 0) {
            const usdInput = document.getElementById('rate-usd-input');
            const eurInput = document.getElementById('rate-eur-input');
            if (usdInput) usdInput.value = formatNumberInput(usdCop);
            if (eurInput) eurInput.value = formatNumberInput(eurCop);

            if (!financeData.exchangeRates) financeData.exchangeRates = {};
            financeData.exchangeRates.USD = round2(usdCop);
            financeData.exchangeRates.EUR = round2(eurCop);
            localStorage.setItem('myFinances', JSON.stringify(financeData));

            showSyncRatesResult(
                true,
                'Tasas actualizadas',
                `
                <div class="glass-sub-box" style="margin-bottom: 0; display: flex; flex-direction: column; gap: 8px;">
                    <div style="display: flex; justify-content: space-between; align-items: center;">
                        <span style="color: var(--text-muted); font-weight: 600;">1 USD (TRM Oficial / Ref.)</span>
                        <strong style="color: var(--text-main); font-size: 13.5px;">${formatMoney(usdCop)} COP</strong>
                    </div>
                    <div style="display: flex; justify-content: space-between; align-items: center; padding-top: 8px; border-top: 1px dashed var(--border-color);">
                        <span style="color: var(--text-muted); font-weight: 600;">1 EUR</span>
                        <strong style="color: var(--text-main); font-size: 13.5px;">${formatMoney(eurCop)} COP</strong>
                    </div>
                </div>
                `
            );
        } else {
            throw new Error('Datos incompletos de las fuentes de divisas.');
        }
    } catch (err) {
        const esc = window.escapeHtml || ((s) => String(s ?? ''));
        showSyncRatesResult(
            false,
            'No se pudo consultar',
            `<p style="margin-bottom: 8px;"><strong style="color: var(--text-main);">${esc(err?.message || 'Error de red')}</strong></p><p style="margin: 0;">Revisa tu conexión a internet o ingresa los valores manualmente.</p>`
        );
    } finally {
        btn.innerHTML = originalText;
        btn.disabled = false;
    }
});

