// ==========================================
// ESCUDO DEFINITIVO CONTRA AUTOCOMPLETADO (NIVEL KERNEL)
// ==========================================
let txManualCategory = null;

// Detectar si el usuario elige la categoría a mano
document.getElementById('trans-category')?.addEventListener('change', (e) => {
    if (e.isTrusted) txManualCategory = e.target.value;
});

const applyKernelShield = () => {
    const accSelect = document.getElementById('account');
    const catSelect = document.getElementById('trans-category');

    if (accSelect && !Object.prototype.hasOwnProperty.call(accSelect, 'value')) {
        accSelect.dataset.kernelShield = '1';
        const origAccSet = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value').set;
        Object.defineProperty(accSelect, 'value', {
            configurable: true,
            set(val) {
                const trip = financeData.tripMode;
                const isSharedOn = !!document.getElementById('tx-is-shared-check')?.checked;
                const payerVal = document.getElementById('tx-hidden-payer')?.value || 'me';
                
                // Si estás en viaje y pagó el acompañante, rechaza cualquier intento de la IA de cambiar la cuenta
                if (trip && trip.active && trip.isShared && isSharedOn && payerVal === 'companion') {
                    if (val !== 'CxC_Gastos_Acompanante') return; 
                }
                origAccSet.call(this, val);
            },
            get() { return Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value').get.call(this); }
        });
    }

    if (catSelect && !Object.prototype.hasOwnProperty.call(catSelect, 'value')) {
        catSelect.dataset.kernelShield = '1';
        const origCatSet = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value').set;
        Object.defineProperty(catSelect, 'value', {
            configurable: true,
            set(val) {
                // Si el usuario ya eligió una categoría manualmente en este registro, rechaza el autocompletado
                if (txManualCategory && val !== txManualCategory) return; 
                origCatSet.call(this, val);
            },
            get() { return Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value').get.call(this); }
        });
    }
};

// Activar el escudo y limpiar memoria manual cada vez que se abre el modal
const shieldTxModal = document.getElementById('transaction-modal');
if (shieldTxModal) {
    new MutationObserver(() => {
        if (!shieldTxModal.classList.contains('hidden')) {
            txManualCategory = null;
            applyKernelShield();
        }
    }).observe(shieldTxModal, { attributes: true, attributeFilter: ['class'] });
}
// ==========================================
// MÓDULO 16: RECOMENDADOR INTELIGENTE DE SALIDA DE DEUDAS
// ==========================================
const renderDebtPlannerSmartRecommendation = () => {
    const box = document.getElementById('planner-smart-recommendation');
    const methodSel = document.getElementById('planner-method');
    if (!box || !methodSel || typeof financeData === 'undefined') return;

    const activeDebts = (financeData.customAccounts || [])
        .filter(a => (a.category === 'debt' || a.category === 'credit_card') && round2(currentBalances[a.id] || 0) > 0)
        .map(a => {
            const bal = round2(currentBalances[a.id] || 0);
            const isCard = a.category === 'credit_card';
            const rawRate = parseFloat(isCard ? (a.rate ?? 0) : (a.debtRate ?? a.interestRate ?? 0)) || 0;
            const rType = isCard ? (a.rateType || 'monthly') : (a.debtRateType || 'monthly');
            const eaRate = rawRate <= 0
                ? 0
                : (rType === 'monthly' ? round2((Math.pow(1 + rawRate / 100, 12) - 1) * 100) : round2(rawRate));
            const minQuota = isCard
                ? (typeof calculateCardMinPaymentEstimate === 'function' ? calculateCardMinPaymentEstimate(a, bal).totalMinPayment : 0)
                : (typeof getDebtMonthlyQuotaBreakdown === 'function' ? getDebtMonthlyQuotaBreakdown(a, bal).totalQuota : (a.debtMonthlyPayment || 0));
            const rawLabel = typeof stripLeadingEmoji === 'function' ? stripLeadingEmoji(a.name) : a.name;
            return {
                id: a.id,
                name: String(rawLabel ?? ''),
                bal,
                eaRate,
                minQuota: round2(minQuota)
            };
        })
        .filter(d => d.eaRate > 0);

    if (activeDebts.length === 0) {
        box.classList.add('hidden');
        box.innerHTML = '';
        return;
    }

    const byRate = [...activeDebts].sort((a, b) => b.eaRate - a.eaRate || a.bal - b.bal);
    const byBalance = [...activeDebts].sort((a, b) => a.bal - b.bal || b.eaRate - a.eaRate);

    const topAvalanche = byRate[0];
    const topSnowball = byBalance[0];
    const currentMethod = methodSel.value || 'avalanche';

    let recMethod = 'avalanche';
    let recTitle = 'Te conviene más: Método Avalancha';
    let recReason = '';

    const escPlan = window.escapeHtml || ((s) => String(s ?? ''));
    const safeAvalName = escPlan(topAvalanche.name);
    const safeSnowName = escPlan(topSnowball.name);

    if (activeDebts.length === 1 || topAvalanche.id === topSnowball.id) {
        recMethod = 'avalanche';
        recTitle = 'Punto de partida ideal: Método Avalancha';
        recReason = activeDebts.length === 1
            ? `Solo tienes una obligación con interés activo (<b>${safeAvalName}</b> al <b>${String(topAvalanche.eaRate).replace('.', ',')}% E.A.</b>), así que ambos métodos siguen exactamente la misma ruta.`
            : `Tu deuda más cara (<b>${safeAvalName}</b>, ${String(topAvalanche.eaRate).replace('.', ',')}% E.A.) también es la de menor saldo (<b>${formatCompact(topAvalanche.bal)}</b>). Ambos métodos la atacan primero.`;
    } else {
        const rateSpread = round2(topAvalanche.eaRate - topSnowball.eaRate);
        const cap = typeof computeDetailedBorrowingCapacity === 'function'
            ? computeDetailedBorrowingCapacity(getMonthId(currentDate))
            : { usedPct: 0, freeCashFlow: 1 };
        const highBurden = cap.usedPct > 35 || cap.freeCashFlow < 0;
        const quickWin = topSnowball.bal <= Math.max(1500000, topAvalanche.bal * 0.35);

        if (activeDebts.length >= 3 && highBurden && quickWin && rateSpread < 10) {
            recMethod = 'snowball';
            recTitle = 'Te conviene más: Método Bola de Nieve';
            recReason = `Tu carga de deuda está al <b>${String(cap.usedPct).replace('.', ',')}%</b> y tienes ${activeDebts.length} obligaciones activas. Liquidar primero <b>${safeSnowName}</b> (<b>${formatCompact(topSnowball.bal)}</b>) libera rápido una cuota de <b>${formatCompact(topSnowball.minQuota)}/mes</b> y te da oxígeno en caja.`;
        } else {
            recMethod = 'avalanche';
            recTitle = 'Te conviene más: Método Avalancha';
            recReason = `<b>${safeAvalName}</b> tiene una tasa del <b>${String(topAvalanche.eaRate).replace('.', ',')}% E.A.</b> (${String(rateSpread).replace('.', ',')} puntos más cara que <b>${safeSnowName}</b>). Priorizarla evita que los intereses sigan creciendo y maximiza tu ahorro total.`;
        }
    }

    const isApplied = currentMethod === recMethod;
    const targetLabel = recMethod === 'avalanche' ? 'Avalancha' : 'Bola de Nieve';

    box.classList.remove('hidden');
    box.innerHTML = `
        <div class="planner-smart-rec-card">
            <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; margin-bottom:4px;">
                <span style="font-size:9.5px; font-weight:800; text-transform:uppercase; letter-spacing:0.4px; color:var(--accent);">Sugerencia según tus finanzas</span>
                ${isApplied
                    ? `<span class="widget-badge good" style="font-size:9.5px; padding:2px 7px;">✓ Activo</span>`
                    : `<button type="button" id="btn-apply-rec-method" class="mini-action-btn" style="font-size:10px; padding:3px 8px;">Usar ${targetLabel}</button>`}
            </div>
            <strong style="display:block; font-size:12.5px; font-weight:800; color:var(--text-main); margin-bottom:3px;">${recTitle}</strong>
            <small style="display:block; font-size:11px; color:var(--text-muted); line-height:1.4;">${recReason}</small>
        </div>
    `;

    box.querySelector('#btn-apply-rec-method')?.addEventListener('click', () => {
        methodSel.value = recMethod;
        methodSel.dispatchEvent(new Event('change'));
    });
};

const debtPlannerModalEl = document.getElementById('debt-planner-modal');
if (debtPlannerModalEl) {
    const plannerObs = new MutationObserver(() => {
        if (!debtPlannerModalEl.classList.contains('hidden')) {
            renderDebtPlannerSmartRecommendation();
        }
    });
    plannerObs.observe(debtPlannerModalEl, { attributes: true, attributeFilter: ['class'] });
    document.getElementById('planner-method')?.addEventListener('change', renderDebtPlannerSmartRecommendation);
}
// ==========================================
// MÓDULO 17: CUADRE RÁPIDO DE EXTRACTO DE TARJETA / CUPO
// ==========================================
window.openCardStatementChargeModal = (acc, currentBal, est) => {
    let modalEl = document.getElementById('card-statement-charge-modal');
    if (!modalEl) {
        modalEl = document.createElement('div');
        modalEl.id = 'card-statement-charge-modal';
        modalEl.className = 'modal hidden';
        modalEl.style.zIndex = '1395';
        modalEl.innerHTML = `
            <div class="modal-content" style="max-width:430px;">
                <div class="modal-header" style="align-items:flex-start; gap:10px;">
                    <div>
                        <h3 style="margin:0; font-size:17px; font-weight:800;">Cuadrar Cargos del Extracto</h3>
                        <small id="csc-card-subtitle" style="color:var(--text-muted); font-size:11.5px;"></small>
                    </div>
                    <button type="button" class="btn-close-modal">Cerrar</button>
                </div>

                <div class="glass-sub-box" style="margin-bottom:12px; padding:11px 12px;">
                    <div style="display:flex; justify-content:space-between; font-size:12px;">
                        <span style="color:var(--text-muted);">Deuda actual en la app:</span>
                        <strong id="csc-current-bal">$ 0,00</strong>
                    </div>
                </div>

                <details class="changelog-accordion" style="margin-bottom:12px; background:rgba(245, 158, 11, 0.08); border:1px solid rgba(245, 158, 11, 0.28); padding:9px 11px; box-shadow:none;">
                    <summary style="font-size:11.5px; font-weight:800; color:#d97706;">
                        <span style="display:inline-flex; align-items:center; gap:6px;">
                            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>
                            ¿Cómo cuadrar tu extracto sin restar a mano?
                        </span>
                        <span>▾</span>
                    </summary>
                    <div style="margin-top:8px; padding-top:8px; border-top:1px dashed rgba(245, 158, 11, 0.3); font-size:11px; color:var(--text-muted); line-height:1.45; display:flex; flex-direction:column; gap:6px;">
                        <span>• <b>Pago Total según Extracto:</b> Escribe el saldo total que reporta el banco al corte; la app calcula sola la diferencia frente a tu saldo actual y descuenta los cargos fijos marcados abajo para no duplicarlos.</span>
                        <span>• <b>Ejemplo:</b> Si en la app debes <b>$ 6.974.470,3</b> y tu extracto dice <b>$ 7.190.945,18</b> (diferencia de <b>$ 216.474,88</b>), al dejar marcada la cuota de manejo de <b>$ 9.451</b>, el campo de intereses se llena solo con <b>$ 207.023,88</b>.</span>
                    </div>
                </details>
                <form id="card-statement-charge-form" class="data-form">
                    <div class="form-group">
                        <label>Pago Total según Extracto ($ • Opc.)</label>
                        <input type="text" id="csc-statement-total" class="money-input" inputmode="decimal" placeholder="Ej. 7.190.945,18">
                        <small style="display:block; font-size:10.5px; color:var(--text-muted); margin-top:4px;">Si lo ingresas, calcula automáticamente la diferencia de intereses y seguros frente a tu saldo actual.</small>
                    </div>

                    <div id="csc-auto-fees-box" class="hidden" style="margin-bottom:10px;">
                        <label class="switch-row" style="padding:8px 10px; margin-bottom:0;">
                            <div>
                                <strong style="font-size:12px;">Incluir cuota de manejo / seguro fijo</strong>
                                <small id="csc-auto-fees-desc" style="font-size:10.5px;"></small>
                            </div>
                            <span class="switch">
                                <input type="checkbox" id="csc-include-auto-fees" checked>
                                <span class="slider"></span>
                            </span>
                        </label>
                    </div>

                    <div class="form-row">
                        <div class="form-group">
                            <label>Intereses / Cargos extra ($)</label>
                            <input type="text" id="csc-extra-charge" class="money-input" inputmode="decimal" placeholder="0,00">
                        </div>
                        <div class="form-group">
                            <label>Fecha del cargo</label>
                            <input type="date" id="csc-charge-date" required>
                        </div>
                    </div>

                    <div class="dash-strip-grid" style="margin-bottom:12px; background:var(--card-inner-bg);">
                        <div class="dash-strip-item" style="text-align:left; border:none; padding-left:6px;">
                            <small>Total a cargar al saldo</small>
                            <strong id="csc-total-to-charge" class="negative" style="font-size:15px;">$ 0,00</strong>
                        </div>
                        <div class="dash-strip-item" style="text-align:right; border:none; padding-right:6px;">
                            <small>Nuevo saldo tarjeta</small>
                            <strong id="csc-new-balance" style="font-size:15px;">$ 0,00</strong>
                        </div>
                    </div>

                    <button type="submit" class="btn btn-primary" style="width:100%;">Cargar al Saldo de la Tarjeta</button>
                </form>
            </div>
        `;
        document.body.appendChild(modalEl);
        modalEl.addEventListener('click', (e) => { if (e.target === modalEl) modalEl.classList.add('hidden'); });
        modalEl.querySelector('.btn-close-modal')?.addEventListener('click', () => modalEl.classList.add('hidden'));
    }

    const totalAutoFees = round2((est.mgmtFeeAmt || 0) + (est.insuranceAmt || 0));
    document.getElementById('csc-card-subtitle').innerText = stripLeadingEmoji(acc.name);
    document.getElementById('csc-current-bal').innerText = formatMoney(currentBal);

    const stmtInput = document.getElementById('csc-statement-total');
    const extraInput = document.getElementById('csc-extra-charge');
    const autoBox = document.getElementById('csc-auto-fees-box');
    const autoCheck = document.getElementById('csc-include-auto-fees');
    const autoDesc = document.getElementById('csc-auto-fees-desc');
    const dateInput = document.getElementById('csc-charge-date');

    stmtInput.value = '';
    extraInput.value = '';
    dateInput.value = currentDate.toLocaleDateString('en-CA');

    if (totalAutoFees > 0) {
        autoBox.classList.remove('hidden');
        autoCheck.checked = true;
        const parts = [];
        if (est.mgmtFeeAmt > 0) parts.push(`Manejo: ${formatMoney(est.mgmtFeeAmt)}`);
        if (est.insuranceAmt > 0) parts.push(`Seguro: ${formatMoney(est.insuranceAmt)}`);
        autoDesc.innerText = parts.join(' • ');
    } else {
        autoBox.classList.add('hidden');
        autoCheck.checked = false;
    }

    const recalcChargePreview = (fromStatementTotal = false) => {
        const autoAmt = (totalAutoFees > 0 && autoCheck.checked) ? totalAutoFees : 0;
        const stmtVal = parseMoneyInput(stmtInput.value);

        if (fromStatementTotal && stmtVal > 0) {
            const totalDiff = Math.max(0, round2(stmtVal - currentBal));
            const remainingInt = Math.max(0, round2(totalDiff - autoAmt));
            extraInput.value = remainingInt > 0 ? formatNumberInput(remainingInt) : '';
        }

        const extraVal = parseMoneyInput(extraInput.value);
        const totalCharge = round2(autoAmt + extraVal);
        document.getElementById('csc-total-to-charge').innerText = formatMoney(totalCharge);
        document.getElementById('csc-new-balance').innerText = formatMoney(round2(currentBal + totalCharge));
    };

    stmtInput.oninput = () => recalcChargePreview(true);
    extraInput.oninput = () => recalcChargePreview(false);
    autoCheck.onchange = () => recalcChargePreview(parseMoneyInput(stmtInput.value) > 0);
    recalcChargePreview(false);

    document.getElementById('card-statement-charge-form').onsubmit = (e) => {
        e.preventDefault();
        const autoAmt = (totalAutoFees > 0 && autoCheck.checked) ? totalAutoFees : 0;
        const extraVal = parseMoneyInput(extraInput.value);
        const totalCharge = round2(autoAmt + extraVal);

        if (totalCharge <= 0) {
            alert('Ingresa el Pago Total del extracto o un valor de cargos mayor a $ 0.');
            return;
        }

        const chosenDateStr = /^\d{4}-\d{2}-\d{2}$/.test(dateInput.value || '')
        ? dateInput.value
        : currentDate.toLocaleDateString('en-CA');
    const now = new Date();
    const parsedDate = new Date(`${chosenDateStr}T${now.toTimeString().slice(0, 5)}`);
    const txDateObj = Number.isNaN(parsedDate.getTime()) ? now : parsedDate;
    const mId = getMonthId(txDateObj);
    const dateLabel = `${txDateObj.toLocaleDateString('es-CO', { day: '2-digit', month: 'short' })}, ${txDateObj.toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit' })}`;
    const intCat = financeData.categories.expense.find(c => stripLeadingEmoji(c.name) === 'Cuotas / Intereses');
    const catName = intCat ? intCat.name : 'Cuotas / Intereses';
    const cleanCardName = stripLeadingEmoji(acc.name);
    const existingIds = new Set(financeData.transactions.map(t => t.id));
    const nextUniqueTxId = (seedOffset) => {
        let candidateId = txDateObj.getTime() + seedOffset;
        while (existingIds.has(candidateId)) {
            candidateId += 1;
        }
        existingIds.add(candidateId);
        return candidateId;
    };

    if (autoAmt > 0) {
        if (est.mgmtFeeAmt > 0) {
            financeData.transactions.push({
                id: nextUniqueTxId(101), monthId: mId, type: 'expense', status: 'closed',
                account: acc.id, category: catName, subcategory: 'General',
                description: `Cuota de manejo (${cleanCardName})`,
                amount: round2(est.mgmtFeeAmt), date: dateLabel, isAdjustment: false
            });
        }
        if (est.insuranceAmt > 0) {
            financeData.transactions.push({
                id: nextUniqueTxId(102), monthId: mId, type: 'expense', status: 'closed',
                account: acc.id, category: catName, subcategory: 'General',
                description: `Seguro vida deudores (${cleanCardName})`,
                amount: round2(est.insuranceAmt), date: dateLabel, isAdjustment: false
            });
        }
    }

    if (extraVal > 0) {
        financeData.transactions.push({
            id: nextUniqueTxId(103), monthId: mId, type: 'expense', status: 'closed',
            account: acc.id, category: catName, subcategory: 'General',
            description: `Intereses y cargos extracto (${cleanCardName})`,
            amount: round2(extraVal), date: dateLabel, isAdjustment: false
        });
    }

        localStorage.setItem('myFinances', JSON.stringify(financeData));
        hasUnsavedChanges = false;
        modalEl.classList.add('hidden');
        updateDashboard();
        openAccountDetail(acc.id, lastAccountViewOrigin);
    };

    modalEl.classList.remove('hidden');
};
// Sincronización automática de reglas de Retefuente (Orden de consumo y Tope Anual/Mensual)
const initTaxRuleSelectors = () => {
    const orderEl = document.getElementById('param-ret-order');
    const capEl = document.getElementById('param-ret-cap-eval');
    const currentParams = (typeof getTaxParams === 'function') ? getTaxParams() : {};
    const legacyRules = financeData.taxParams || {};
    const activeOrder = currentParams.retOrder || legacyRules.retOrder || 'salary_first';
    const activeCapEval = currentParams.retCapEval || legacyRules.retCapEval || 'monthly';

    if (orderEl) orderEl.value = activeOrder;
    if (capEl) capEl.value = activeCapEval;

    const persistTaxRules = () => {
        const nextOrder = orderEl?.value || 'salary_first';
        const nextCap = capEl?.value || 'monthly';
        if (typeof saveTaxParams === 'function' && typeof getTaxParams === 'function') {
            saveTaxParams({
                ...getTaxParams(),
                retOrder: nextOrder,
                retCapEval: nextCap
            });
        }
        financeData.taxParams = { ...(financeData.taxParams || {}), retOrder: nextOrder, retCapEval: nextCap };
        localStorage.setItem('myFinances', JSON.stringify(financeData));
        if (typeof renderSalaryUI === 'function') renderSalaryUI(false);
        if (typeof renderBonusSimulator === 'function') renderBonusSimulator();
    };

    orderEl?.addEventListener('change', persistTaxRules);
    capEl?.addEventListener('change', persistTaxRules);
    document.getElementById('tax-params-form')?.addEventListener('submit', persistTaxRules);
};
initTaxRuleSelectors();
// Garantizar que Cuentas y Liquidez NUNCA abra con ambas sub-vistas en .hidden y ocupe el 100% del alto
const accModalFix = document.getElementById('accounts-modal');
if (accModalFix) {
    const resetAccountsView = () => {
        document.getElementById('account-detail-view')?.classList.add('hidden');
        document.getElementById('accounts-list-view')?.classList.remove('hidden');
    };

    const expandAccountDetailScroll = () => {
        const detailView = document.getElementById('account-detail-view');
        if (!detailView || detailView.classList.contains('hidden')) return;
        detailView.style.setProperty('max-height', 'none', 'important');
        detailView.style.setProperty('margin-bottom', '0', 'important');

        const scrollChild = Array.from(detailView.children).find(el => {
            const ov = window.getComputedStyle(el).overflowY;
            return ov === 'auto' || ov === 'scroll';
        });
        if (scrollChild) {
            scrollChild.style.setProperty('flex', '1 1 auto', 'important');
            scrollChild.style.setProperty('min-height', '0', 'important');
            scrollChild.style.setProperty('max-height', 'none', 'important');
            scrollChild.style.setProperty('height', 'auto', 'important');
            scrollChild.style.setProperty('margin-bottom', '0', 'important');
            scrollChild.style.setProperty('padding-bottom', 'calc(20px + env(safe-area-inset-bottom, 0px))', 'important');
        }
    };
    
    // 1. Si hace clic en el fondo oscuro (por fuera) o en cualquier botón "Cerrar"
    accModalFix.addEventListener('click', (e) => {
        if (e.target === accModalFix) resetAccountsView();
    });
    accModalFix.querySelectorAll('.btn-close-modal').forEach(btn => {
        btn.addEventListener('click', resetAccountsView);
    });

    // 2. Vigilar apertura del modal y de la vista de detalle
    const accObserver = new MutationObserver(() => {
        if (!accModalFix.classList.contains('hidden')) {
            const listView = document.getElementById('accounts-list-view');
            const detailView = document.getElementById('account-detail-view');
            if (listView?.classList.contains('hidden') && detailView?.classList.contains('hidden')) {
                resetAccountsView();
            }
            expandAccountDetailScroll();
        }
    });
    accObserver.observe(accModalFix, { attributes: true, attributeFilter: ['class'] });

    const detailViewEl = document.getElementById('account-detail-view');
    if (detailViewEl) {
        new MutationObserver(expandAccountDetailScroll).observe(detailViewEl, { attributes: true, attributeFilter: ['class'] });
    }
}
// Vista previa de Comisión por Avance al transferir desde Tarjeta de Crédito
const renderTransactionTcAdvancePreview = () => {
    const type = document.getElementById('type')?.value || 'expense';
    const accountId = document.getElementById('account')?.value || '';
    const toAccountId = document.getElementById('to-account')?.value || '';
    const rawAmt = parseMoneyInput(document.getElementById('amount')?.value);
    const editId = document.getElementById('edit-id')?.value;

    let box = document.getElementById('tx-tc-advance-fee-box');
    const acc = typeof getAccountObj === 'function' ? getAccountObj(accountId) : null;
    const feeAmt = (acc && acc.category === 'credit_card' && acc.hasAdvanceFee) ? round2(acc.advanceFee || 0) : 0;

    if (editId || type !== 'transfer' || feeAmt <= 0 || !toAccountId || toAccountId === accountId || rawAmt <= 0) {
        if (box) {
            box.classList.add('hidden');
            box.innerHTML = '';
        }
        return;
    }

    if (!box) {
        box = document.createElement('div');
        box.id = 'tx-tc-advance-fee-box';
        box.className = 'glass-sub-box';
        box.style.cssText = 'margin-bottom:12px; padding:10px 12px; border-color:rgba(245, 158, 11, 0.35); background:rgba(245, 158, 11, 0.08);';
        const anchor = document.getElementById('tx-gmf-impact-box') || document.getElementById('amount')?.closest('.form-group');
        if (anchor) anchor.insertAdjacentElement('afterend', box);
    }

    const escAdv = window.escapeHtml || ((s) => String(s ?? ''));
    const fxRate = (typeof activeTxCurrency !== 'undefined' && activeTxCurrency !== 'COP')
        ? ((financeData.exchangeRates && financeData.exchangeRates[activeTxCurrency]) || (activeTxCurrency === 'USD' ? 4150 : 4420))
        : 1;
    const amountCop = round2(rawAmt * fxRate);
    const toAcc = typeof getAccountObj === 'function' ? getAccountObj(toAccountId) : null;
    const destName = escAdv(toAcc ? stripLeadingEmoji(toAcc.name) : 'Cuenta destino');
    const cardName = escAdv(stripLeadingEmoji(acc.name));
    const prevChecked = document.getElementById('tx-apply-tc-advance-fee')?.checked !== false;
    const totalCardCharge = prevChecked ? round2(amountCop + feeAmt) : amountCop;

    box.classList.remove('hidden');
    box.innerHTML = `
        <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; margin-bottom:5px;">
            <span style="font-size:11.5px; font-weight:800; color:#d97706;">Comisión por avance (${cardName}):</span>
            <strong class="negative" style="font-size:12.5px; white-space:nowrap;">+ ${formatMoney(feeAmt)}</strong>
        </div>
        <div style="display:flex; justify-content:space-between; align-items:center; font-size:11px; color:var(--text-muted); margin-bottom:3px;">
            <span>Recibe ${destName}:</span>
            <strong class="positive">${formatMoney(amountCop)}</strong>
        </div>
        <div style="display:flex; justify-content:space-between; align-items:center; font-size:11.5px; padding-bottom:6px; margin-bottom:6px; border-bottom:1px dashed rgba(245, 158, 11, 0.3);">
            <span style="color:var(--text-main); font-weight:700;">Total cargado a la tarjeta:</span>
            <strong style="color:var(--text-main);">${formatMoney(totalCardCharge)}</strong>
        </div>
        <label style="display:flex; align-items:center; gap:7px; font-size:11px; font-weight:700; color:var(--text-main); cursor:pointer;">
            <input type="checkbox" id="tx-apply-tc-advance-fee" ${prevChecked ? 'checked' : ''} style="width:15px; height:15px; accent-color:#d97706;">
            <span>Sumar comisión por avance a la deuda de la tarjeta</span>
        </label>
    `;

    box.querySelector('#tx-apply-tc-advance-fee')?.addEventListener('change', renderTransactionTcAdvancePreview);
};

['amount', 'account', 'to-account', 'type'].forEach(id => {
    const el = document.getElementById(id);
    if (el) {
        el.addEventListener('input', renderTransactionTcAdvancePreview);
        el.addEventListener('change', renderTransactionTcAdvancePreview);
    }
});

// ==========================================
// TUTORIAL INTERACTIVO POST-REGISTRO (COACHMARKS)
// ==========================================
window.startAppCoachmarks = (forceReplay = false) => {
    if (!forceReplay && localStorage.getItem('myFinancesCoachmarksDone') === 'true') return;
    if (document.body.classList.contains('app-locked') || window.LumenSecurity?.isVaultLocked?.()) return;
    if (!forceReplay && typeof isAnyModalOpen === 'function' && isAnyModalOpen()) return;

    document.getElementById('app-coachmark-overlay')?.remove();

    const steps = [
        {
            // Botón principal "+" (#fab-btn)
            selector: '#fab-btn, #open-modal-btn, #add-btn, .fab-container > button:last-of-type',
            radius: '50%',
            padding: 7,
            title: 'Registra un movimiento',
            desc: 'Toca + para anotar un gasto, ingreso o transferencia. Elige la cuenta, la categoría y guarda en segundos.'
        },
        {
            // Botón flotante de Lumi (si tiene otro id en index.html o assistant.js, ponlo aquí primero)
            selector: '#btn-open-lumi, #lumi-fab, #assistant-fab, .fab-container > button:first-of-type',
            radius: '50%',
            padding: 7,
            title: 'Pregunta a Lumi, tu copiloto',
            desc: 'Toca este botón para consultar tus finanzas 100% sin conexión: simula abonos a deudas, revisa qué tarjeta te conviene o proyecta tu cierre de mes.'
        },
        {
            selector: '.bottom-nav',
            radius: '36px',
            padding: 6,
            title: 'Tu navegación principal',
            desc: 'Cambia al instante entre Resumen, tus gráficas de Análisis y el control mensual de Presupuesto.'
        },
        {
            selector: '.hamburger-btn',
            radius: '18px',
            padding: 7,
            title: 'Cuentas, deudas y herramientas',
            desc: 'Abre el menú lateral para gestionar tus cuentas, tarjetas de crédito, préstamos, bolsillos de ahorro y simuladores.'
        },
        {
            selector: '.profile-avatar',
            radius: '50%',
            padding: 7,
            title: 'Ajustes y tu seguridad',
            desc: 'Tus datos se guardan cifrados solo en este teléfono, sin nube. En tu perfil configuras el bloqueo con PIN, tu nómina y copias de respaldo.'
        }
    ].filter(s => {
        const el = document.querySelector(s.selector);
        if (!el) return false;
        const r = el.getBoundingClientRect();
        return r.width > 0 && r.height > 0;
    });

    if (steps.length === 0) return;

    let currentStep = 0;

    const overlay = document.createElement('div');
    overlay.id = 'app-coachmark-overlay';
    overlay.className = 'coachmark-overlay';
    overlay.innerHTML = `
        <div class="coachmark-spotlight" id="coachmark-spotlight"></div>
        <button type="button" class="coachmark-skip-pill is-top" id="coachmark-skip-btn">Saltar</button>
        <div class="coachmark-card arrow-bottom" id="coachmark-card" role="dialog" aria-live="polite">
            <div class="coachmark-arrow"></div>
            <span class="coachmark-step-eyebrow" id="coachmark-eyebrow">1 DE ${steps.length}</span>
            <h3 class="coachmark-title" id="coachmark-title"></h3>
            <p class="coachmark-desc" id="coachmark-desc"></p>
            <div class="coachmark-card-footer">
                <div class="coachmark-dots" id="coachmark-dots"></div>
                <span class="coachmark-next-hint" id="coachmark-next-hint">Toca para seguir ›</span>
            </div>
        </div>
    `;
    document.body.appendChild(overlay);

    const spotlightEl = document.getElementById('coachmark-spotlight');
    const cardEl = document.getElementById('coachmark-card');
    const skipBtn = document.getElementById('coachmark-skip-btn');
    const eyebrowEl = document.getElementById('coachmark-eyebrow');
    const titleEl = document.getElementById('coachmark-title');
    const descEl = document.getElementById('coachmark-desc');
    const dotsEl = document.getElementById('coachmark-dots');
    const nextHintEl = document.getElementById('coachmark-next-hint');

    const cleanup = () => {
        localStorage.setItem('myFinancesCoachmarksDone', 'true');
        window.removeEventListener('resize', renderStep);
        window.visualViewport?.removeEventListener('resize', renderStep);
        overlay.remove();
    };

    const renderStep = () => {
        const step = steps[currentStep];
        const target = document.querySelector(step.selector);
        if (!target) {
            cleanup();
            return;
        }

        const rect = target.getBoundingClientRect();
        const pad = step.padding || 8;
        const spotLeft = Math.max(4, rect.left - pad);
        const spotTop = Math.max(4, rect.top - pad);
        const spotWidth = Math.min(window.innerWidth - 8, rect.width + pad * 2);
        const spotHeight = rect.height + pad * 2;

        spotlightEl.style.left = `${spotLeft}px`;
        spotlightEl.style.top = `${spotTop}px`;
        spotlightEl.style.width = `${spotWidth}px`;
        spotlightEl.style.height = `${spotHeight}px`;
        spotlightEl.style.borderRadius = step.radius;

        eyebrowEl.textContent = `${currentStep + 1} DE ${steps.length}`;
        titleEl.textContent = step.title;
        descEl.textContent = step.desc;
        nextHintEl.textContent = currentStep === steps.length - 1 ? '¡Empezar! ✓' : 'Toca para seguir ›';
        dotsEl.innerHTML = steps
            .map((_, idx) => `<span class="${idx === currentStep ? 'active' : ''}"></span>`)
            .join('');

        const vw = window.innerWidth;
        const vh = window.innerHeight;
        const cardWidth = Math.min(340, vw - 32);
        const targetCenterX = rect.left + rect.width / 2;
        const cardLeft = Math.max(16, Math.min(vw - cardWidth - 16, targetCenterX - cardWidth / 2));
        const arrowX = Math.max(24, Math.min(cardWidth - 24, targetCenterX - cardLeft));

        cardEl.style.left = `${cardLeft}px`;
        cardEl.style.setProperty('--arrow-left', `${arrowX}px`);

        const isTargetInLowerHalf = (rect.top + rect.height / 2) > vh * 0.5;
        if (isTargetInLowerHalf) {
            cardEl.classList.remove('arrow-top');
            cardEl.classList.add('arrow-bottom');
            cardEl.style.top = 'auto';
            cardEl.style.bottom = `${vh - spotTop + 14}px`;
            skipBtn.classList.remove('is-bottom');
            skipBtn.classList.add('is-top');
        } else {
            cardEl.classList.remove('arrow-bottom');
            cardEl.classList.add('arrow-top');
            cardEl.style.bottom = 'auto';
            cardEl.style.top = `${spotTop + spotHeight + 14}px`;
            skipBtn.classList.remove('is-top');
            skipBtn.classList.add('is-bottom');
        }
    };

    skipBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        cleanup();
    });

    overlay.addEventListener('click', () => {
        if (currentStep < steps.length - 1) {
            currentStep++;
            renderStep();
        } else {
            cleanup();
        }
    });

    window.addEventListener('resize', renderStep);
    window.visualViewport?.addEventListener('resize', renderStep);
    renderStep();
    setTimeout(renderStep, 340);
};

// Detectar automáticamente cuando termina el registro inicial y ya no hay modales superpuestos
(() => {
    let coachTimer = null;
    const scheduleCoachmarks = () => {
        if (localStorage.getItem('myFinancesCoachmarksDone') === 'true') return;
        if (coachTimer) clearTimeout(coachTimer);
        coachTimer = setTimeout(() => {
            coachTimer = null;
            window.startAppCoachmarks(false);
        }, 420);
    };

    const authOverlay = document.getElementById('auth-overlay');
    if (authOverlay) {
        const observer = new MutationObserver(() => {
            if (authOverlay.classList.contains('hidden') && localStorage.getItem('myFinancesAuth')) {
                scheduleCoachmarks();
            }
        });
        observer.observe(authOverlay, { attributes: true, attributeFilter: ['class'] });
    }

    document.addEventListener('click', (ev) => {
        if (localStorage.getItem('myFinancesCoachmarksDone') === 'true') return;
        if (ev.target.closest('#btn-done-recovery-modal, .btn-close-modal, #btn-later-gmf-welcome, #btn-save-gmf-welcome, #btn-none-gmf-welcome')) {
            setTimeout(scheduleCoachmarks, 320);
        }
    });

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', scheduleCoachmarks);
    } else {
        scheduleCoachmarks();
    }
})();

window.openBentoConfirmModal = ({
    title = '¿Confirmar acción?',
    subtitle = '',
    message = '',
    confirmText = 'Confirmar',
    cancelText = 'Cancelar',
    danger = true,
    onConfirm
}) => {
    document.getElementById('bento-confirm-modal')?.remove();

    const esc = window.escapeHtml || ((s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])));
    const safeTitle = esc(title);
    const safeSubtitle = subtitle ? esc(subtitle) : '';
    const safeCancel = esc(cancelText);
    const safeConfirm = esc(confirmText);

    const hasCancel = Boolean(cancelText && cancelText.trim() !== '');
    const toneColor = danger ? 'var(--negative)' : 'var(--accent)';
    const toneBg = danger ? 'var(--negative-bg)' : 'var(--accent-soft)';
    const okBtnBg = danger ? 'var(--negative)' : 'var(--theme-gradient)';
    const iconSvg = danger
        ? `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><line x1="10" y1="11" x2="10" y2="17"/><line x1="14" y1="11" x2="14" y2="17"/></svg>`
        : `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>`;

    const modal = document.createElement('div');
    modal.id = 'bento-confirm-modal';
    modal.className = 'modal';
    modal.style.zIndex = '2750';
    modal.innerHTML = `
        <div class="modal-content" style="max-width: 380px; padding: 22px 20px; box-shadow: 0 22px 44px rgba(0, 0, 0, 0.24);">
            <div style="display: flex; align-items: center; gap: 11px; margin-bottom: 12px;">
                <span class="drawer-icon-box" style="width: 38px; height: 38px; flex-shrink: 0; background: ${toneBg}; color: ${toneColor};">
                    ${iconSvg}
                </span>
                <div style="min-width: 0;">
                    <h3 style="margin: 0; color: var(--text-main); font-size: 16.5px; font-weight: 800; line-height: 1.25;">${safeTitle}</h3>
                    ${safeSubtitle ? `<small style="display: block; color: var(--text-muted); font-size: 11px; margin-top: 2px;">${safeSubtitle}</small>` : ''}
                </div>
            </div>

            <div class="glass-sub-box" style="margin-bottom: 16px; font-size: 13px; line-height: 1.48; color: var(--text-main);">
                ${message}
            </div>

            <div style="display: grid; grid-template-columns: ${hasCancel ? '1fr 1.35fr' : '1fr'}; gap: 8px;">
                ${hasCancel ? `<button type="button" id="bento-confirm-cancel-btn" class="btn btn-secondary" style="width: 100%; padding: 11px 12px; font-size: 13.5px;">${safeCancel}</button>` : ''}
                <button type="button" id="bento-confirm-ok-btn" class="btn btn-primary" style="width: 100%; padding: 12px 14px; font-size: 13.5px; font-weight: 700; background: ${okBtnBg}; border: none;">${safeConfirm}</button>
            </div>
        </div>
    `;
    document.body.appendChild(modal);

    const closeModal = () => modal.remove();
    let backdropDown = false;
    modal.addEventListener('pointerdown', (e) => { backdropDown = (e.target === modal); });
    modal.addEventListener('click', (e) => {
        if (e.target === modal && backdropDown) closeModal();
        backdropDown = false;
    });
    modal.querySelector('#bento-confirm-cancel-btn')?.addEventListener('click', closeModal);
    modal.querySelector('#bento-confirm-ok-btn')?.addEventListener('click', () => {
        closeModal();
        if (typeof onConfirm === 'function') onConfirm();
    });
};
// ==========================================
// SELECTORES BENTO UI PARA TRANSACCIONES
// ==========================================
(() => {
    const PICKER_IDS = Array.from(document.querySelectorAll('.bento-select-trigger'))
        .map(btn => btn.getAttribute('data-target-select'))
        .filter(Boolean);
    const pickerModal = document.getElementById('bento-picker-modal');
    const pickerList = document.getElementById('bento-picker-list');
    const pickerTitle = document.getElementById('bento-picker-title');
    const pickerSubtitle = document.getElementById('bento-picker-subtitle');
    const pickerIcon = document.getElementById('bento-picker-icon');
    const searchWrap = document.getElementById('bento-picker-search-wrap');
    const searchInput = document.getElementById('bento-picker-search');

    if (!pickerModal || !pickerList) return;

    let activeSelect = null;

    const parseOptionLabel = (rawText) => {
        let label = (rawText || '').trim();
        let isDefault = false;
        let amountBadge = '';

        if (/[★⭐]/.test(label)) {
            isDefault = true;
            label = label.replace(/[★⭐]/g, '').trim();
        }
        const amtMatch = label.match(/\(([^)]*\$[^)]*)\)\s*$/);
        if (amtMatch) {
            amountBadge = amtMatch[1].trim();
            label = label.replace(amtMatch[0], '').trim();
        }
        return { label, isDefault, amountBadge };
    };

    const syncTriggerButton = (selectId) => {
        const selectEl = document.getElementById(selectId);
        const triggerBtn = document.getElementById(`bento-trigger-${selectId}`);
        if (!selectEl || !triggerBtn) return;

        const textSpan = triggerBtn.querySelector('.bento-trigger-text');
        const selectedOpt = selectEl.options[selectEl.selectedIndex];

        if (selectedOpt && selectedOpt.value !== '') {
            const { label, isDefault } = parseOptionLabel(selectedOpt.textContent);
            textSpan.textContent = isDefault ? `${label} ★` : label;
            textSpan.style.color = 'var(--text-main)';
        } else {
            textSpan.textContent = selectedOpt ? selectedOpt.textContent : 'Seleccionar...';
            textSpan.style.color = 'var(--text-muted)';
        }

        // Sincronizar bloqueo (ej. cuando en Modo Viaje pagó el acompañante)
        const isLocked = selectEl.disabled || selectEl.style.pointerEvents === 'none';
        triggerBtn.style.opacity = isLocked ? '0.68' : '1';
        triggerBtn.style.pointerEvents = isLocked ? 'none' : 'auto';
    };

    const getGroupIconSvg = (groupLabel, isCategory) => {
        const lower = (groupLabel || '').toLowerCase();
        if (isCategory) {
            return `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"/><line x1="7" y1="7" x2="7.01" y2="7"/></svg>`;
        }
        if (lower.includes('tarjeta') || lower.includes('crédito')) {
            return `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="5" width="20" height="14" rx="2"/><line x1="2" y1="10" x2="22" y2="10"/></svg>`;
        }
        if (lower.includes('cobrar') || lower.includes('favor')) {
            return `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="8.5" cy="7" r="4"/><polyline points="17 11 19 13 23 9"/></svg>`;
        }
        if (lower.includes('bolsillo') || lower.includes('ahorro')) {
            return `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M19 5c-1.5 0-2.8 1.4-3 2-3.5-1.5-11-.3-11 5 0 1.8 0 3 2 4.5V20h4v-2h3v2h4v-4c1-.5 1.7-1 2-2h2v-4h-2c0-1-.5-1.5-1-2V5z"/></svg>`;
        }
        return `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="6" width="20" height="12" rx="2"/><circle cx="12" cy="12" r="2"/></svg>`;
    };

    const getLiveAccountBadge = (optValue, existingBadge, isCategory) => {
        if (existingBadge) return { text: existingBadge, style: '' };
        if (isCategory || !optValue || optValue === 'adjustment' || optValue === 'CxC_Gastos_Acompanante') {
            return { text: '', style: '' };
        }
        if (typeof formatMoney !== 'function' || typeof financeData === 'undefined') {
            return { text: '', style: '' };
        }

        const valStr = String(optValue);
        const balMap = (typeof currentBalances !== 'undefined' && currentBalances) ? currentBalances : {};
        const hasBal = Object.prototype.hasOwnProperty.call(balMap, valStr);
        const rawBal = hasBal ? Number(balMap[valStr]) : null;

        // 1. Bolsillos de Ahorro
        const pocket = (financeData.pockets || []).find(p => String(p.id) === valStr);
        if (pocket) {
            const pBal = rawBal !== null
                ? rawBal
                : (typeof computePocketMetrics === 'function'
                    ? computePocketMetrics(pocket).balance
                    : Number(pocket.saved || 0) + Number(pocket.yields || 0));
            return { text: formatMoney(pBal), style: '' };
        }

        // 2. Cuentas, Deudas a Favor, Tarjetas o Préstamos
        const acc = (financeData.customAccounts || []).find(a => String(a.id) === valStr);
        if (acc) {
            if (acc.category === 'credit_card') {
                const limit = Number(acc.creditLimit || 0);
                const debt = rawBal !== null ? rawBal : 0;
                if (limit > 0) {
                    const avail = Math.max(0, limit - debt);
                    return {
                        text: `Disp: ${formatMoney(avail)}`,
                        style: 'color: var(--positive); background: var(--positive-bg);'
                    };
                }
                return { text: formatMoney(debt), style: '' };
            }
            if (acc.category === 'debt') {
                return {
                    text: formatMoney(rawBal !== null ? rawBal : 0),
                    style: 'color: var(--negative); background: var(--negative-bg);'
                };
            }
            if (rawBal !== null) {
                const negStyle = rawBal < 0 ? 'color: var(--negative); background: var(--negative-bg);' : '';
                return { text: formatMoney(rawBal), style: negStyle };
            }
        } else if (rawBal !== null) {
            const negStyle = rawBal < 0 ? 'color: var(--negative); background: var(--negative-bg);' : '';
            return { text: formatMoney(rawBal), style: negStyle };
        }

        return { text: '', style: '' };
    };

    const renderPickerOptions = (filterText = '') => {
        if (!activeSelect) return;
        const query = filterText.trim().toLowerCase();
        const isCategory = activeSelect.id === 'trans-category'
            || activeSelect.id === 'quick-action-category'
            || activeSelect.id.startsWith('split-cat-')
            || activeSelect.id.includes('category');
        const currentVal = activeSelect.value;

        const groups = [];
        const optgroups = activeSelect.querySelectorAll('optgroup');

        if (optgroups.length > 0) {
            optgroups.forEach(og => {
                const opts = Array.from(og.querySelectorAll('option')).filter(o => !o.disabled && o.value !== '');
                if (opts.length > 0) groups.push({ label: og.label, options: opts });
            });
            const looseOpts = Array.from(activeSelect.children).filter(el => el.tagName === 'OPTION' && !el.disabled && el.value !== '');
            if (looseOpts.length > 0) {
                groups.unshift({ label: isCategory ? 'General' : 'Otras opciones', options: looseOpts });
            }
        } else {
            const opts = Array.from(activeSelect.querySelectorAll('option')).filter(o => !o.disabled && o.value !== '');
            groups.push({ label: '', options: opts });
        }

        let html = '';
        let totalVisible = 0;

        groups.forEach(g => {
            const filtered = g.options.filter(opt => {
                if (!query) return true;
                return opt.textContent.toLowerCase().includes(query) || g.label.toLowerCase().includes(query);
            });
            if (filtered.length === 0) return;
            totalVisible += filtered.length;

            const escPick = window.escapeHtml || ((s) => String(s ?? ''));
            const escPickAttr = window.escapeAttr || escPick;
            html += `<div>`;
            if (g.label) {
                html += `
                    <div class="bento-picker-group-label">
                        <span style="color: var(--accent); display: inline-flex;">${getGroupIconSvg(g.label, isCategory)}</span>
                        <span>${escPick(g.label)}</span>
                    </div>
                `;
            }
            html += `<div class="bento-picker-island">`;
            filtered.forEach(opt => {
                const isSelected = String(opt.value) === String(currentVal);
                const { label, isDefault, amountBadge } = parseOptionLabel(opt.textContent);
                const badge = getLiveAccountBadge(opt.value, amountBadge, isCategory);
                html += `
                    <button type="button" class="bento-picker-option ${isSelected ? 'selected' : ''}" data-opt-value="${escPickAttr(opt.value)}">
                        <div style="min-width: 0; flex: 1;">
                            <div class="bento-picker-opt-title">
                                <span>${escPick(label)}</span>
                                ${isDefault ? `<span class="bento-picker-star-pill">★ Predet.</span>` : ''}
                            </div>
                        </div>
                        <div style="display: flex; align-items: center; gap: 8px; flex-shrink: 0;">
                            ${badge.text ? `<span class="bento-picker-amt-pill" style="${badge.style}">${escPick(badge.text)}</span>` : ''}
                            ${isSelected ? `<span class="bento-picker-check"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg></span>` : ''}
                        </div>
                    </button>
                `;
            });
            html += `</div></div>`;
        });

        if (totalVisible === 0) {
            html = `<div style="text-align: center; padding: 28px 12px; color: var(--text-muted); font-size: 13px;">No se encontraron resultados.</div>`;
        }

        pickerList.innerHTML = html;
    };

    const closeBentoPicker = () => {
        pickerModal.classList.add('hidden');
        activeSelect = null;
        if (searchInput) searchInput.value = '';
    };

    const openBentoPicker = (selectId) => {
        const selectEl = document.getElementById(selectId);
        if (!selectEl) return;
        activeSelect = selectEl;

        const isCategory = selectId === 'trans-category' || selectId.startsWith('split-cat-') || selectId.includes('category');
        const isAccountField = selectId === 'account' || selectId === 'to-account' || selectId.startsWith('split-acc-') || selectId.includes('account') || selectId.includes('acc');
        const triggerBtn = document.getElementById(`bento-trigger-${selectId}`);
        const siblingLabel = triggerBtn?.closest('.form-group')?.querySelector('label');
        const dynamicTitle = (siblingLabel ? siblingLabel.textContent.trim() : '') || selectEl.getAttribute('aria-label') || 'Seleccionar opción';

        pickerTitle.textContent = isCategory ? 'Seleccionar Categoría' : dynamicTitle;
        pickerSubtitle.textContent = isCategory
            ? 'Elige la categoría del movimiento'
            : (isAccountField ? 'Selecciona el origen o destino del dinero' : 'Toca una opción para elegir');

        pickerIcon.innerHTML = getGroupIconSvg(isCategory ? 'cat' : (isAccountField ? 'liquidez' : 'cat'), !isAccountField);

        const totalOpts = selectEl.querySelectorAll('option').length;
        if (searchWrap) {
            searchWrap.classList.toggle('hidden', totalOpts <= 7);
            if (searchInput) searchInput.value = '';
        }

        renderPickerOptions('');
        document.body.appendChild(pickerModal);
        pickerModal.classList.remove('hidden');
    };

    // Enlazar disparadores estáticos y convertir automáticamente cualquier <select> dinámico en modales
    const valueDesc = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value');

    const bindBentoSelect = (selectEl) => {
        if (!selectEl || selectEl.dataset.bentoBound === '1') return;

        if (!selectEl.id) {
            selectEl.id = 'bento-auto-sel-' + Math.random().toString(36).slice(2, 8);
        }
        const selectId = selectEl.id;
        let triggerBtn = document.getElementById(`bento-trigger-${selectId}`);

        // Si el <select> fue creado dinámicamente por JS y no tiene botón Bento, crearlo automáticamente
        if (!triggerBtn) {
            if (selectEl.classList.contains('hidden') || selectEl.getAttribute('aria-hidden') === 'true') return;
            if (!selectEl.closest('.modal') && selectEl.dataset.bentoCompact !== '1') return;

            triggerBtn = document.createElement('button');
            triggerBtn.type = 'button';
            triggerBtn.id = `bento-trigger-${selectId}`;
            triggerBtn.className = 'bento-select-trigger';
            triggerBtn.setAttribute('data-target-select', selectId);
            triggerBtn.setAttribute('aria-haspopup', 'listbox');
            if (selectEl.dataset.bentoCompact === '1') {
                triggerBtn.style.cssText = 'width: auto; min-height: 30px; padding: 4px 10px; font-size: 11.5px; font-weight: 700; border-radius: 10px; flex-shrink: 0;';
            }
            triggerBtn.innerHTML = `
                <span class="bento-trigger-text">Seleccionar...</span>
                <svg class="bento-trigger-chevron" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>
            `;

            selectEl.classList.add('hidden');
            selectEl.setAttribute('aria-hidden', 'true');
            selectEl.tabIndex = -1;
            selectEl.parentNode.insertBefore(triggerBtn, selectEl);
        }

        if (selectEl.required) {
            selectEl.dataset.wasRequired = '1';
            selectEl.required = false;
        }
        selectEl.dataset.bentoBound = '1';
        triggerBtn.addEventListener('click', () => openBentoPicker(selectId));
        selectEl.addEventListener('change', () => syncTriggerButton(selectId));
        selectEl.form?.addEventListener('reset', () => setTimeout(() => syncTriggerButton(selectId), 0));

        if (valueDesc && valueDesc.get && valueDesc.set) {
            Object.defineProperty(selectEl, 'value', {
                configurable: true,
                get() { return valueDesc.get.call(this); },
                set(val) {
                    if (selectId === 'account') {
                        const trip = typeof financeData !== 'undefined' ? financeData.tripMode : null;
                        const isSharedOn = !!document.getElementById('tx-is-shared-check')?.checked;
                        const payerVal = document.getElementById('tx-hidden-payer')?.value || 'me';
                        if (trip && trip.active && trip.isShared && isSharedOn && payerVal === 'companion' && val !== 'CxC_Gastos_Acompanante') {
                            return;
                        }
                    }
                    if (selectId === 'trans-category' && typeof txManualCategory !== 'undefined' && txManualCategory && val !== txManualCategory) {
                        return;
                    }
                    valueDesc.set.call(this, val);
                    syncTriggerButton(selectId);
                }
            });
        }

        const obs = new MutationObserver(() => syncTriggerButton(selectId));
        obs.observe(selectEl, { childList: true, subtree: true, attributes: true, attributeFilter: ['style', 'disabled'] });
        syncTriggerButton(selectId);
    };

    // 1. Enlazar todos los triggers que ya vienen en index.html
    document.querySelectorAll('.bento-select-trigger').forEach(btn => {
        const targetId = btn.getAttribute('data-target-select');
        const sel = targetId ? document.getElementById(targetId) : null;
        if (sel) bindBentoSelect(sel);
    });

    // 2. Detectar y convertir automáticamente cualquier <select> dinámico que se inyecte en el DOM
    const DYNAMIC_SELECT_SELECTOR = '.modal select:not(.hidden), select[data-bento-compact="1"]:not(.hidden)';
    document.querySelectorAll(DYNAMIC_SELECT_SELECTOR).forEach(bindBentoSelect);
    const selectDomObserver = new MutationObserver((mutations) => {
        mutations.forEach(m => {
            m.addedNodes.forEach(node => {
                if (node.nodeType !== 1) return;
                if (node.matches && node.matches(DYNAMIC_SELECT_SELECTOR)) bindBentoSelect(node);
                node.querySelectorAll?.(DYNAMIC_SELECT_SELECTOR).forEach(bindBentoSelect);
            });
        });
    });
    selectDomObserver.observe(document.body, { childList: true, subtree: true });

    document.getElementById('type')?.addEventListener('change', () => {
        if (typeof txManualCategory !== 'undefined') txManualCategory = null;
    });
    document.getElementById('transaction-form')?.addEventListener('reset', () => {
        if (typeof txManualCategory !== 'undefined') txManualCategory = null;
    });

    pickerList.addEventListener('click', (e) => {
        const optBtn = e.target.closest('.bento-picker-option');
        if (!optBtn || !activeSelect) return;

        const chosenVal = optBtn.getAttribute('data-opt-value');
        if (activeSelect.id === 'trans-category' && typeof txManualCategory !== 'undefined') {
            txManualCategory = chosenVal;
        }
        if (activeSelect.id === 'account' && typeof tripUserOverrodeAccount !== 'undefined') {
            tripUserOverrodeAccount = true;
        }
        activeSelect.value = chosenVal;
        activeSelect.dispatchEvent(new Event('change', { bubbles: true }));
        activeSelect.dispatchEvent(new Event('input', { bubbles: true }));
        syncTriggerButton(activeSelect.id);
        closeBentoPicker();
    });

    searchInput?.addEventListener('input', (e) => renderPickerOptions(e.target.value));
    document.getElementById('close-bento-picker-btn')?.addEventListener('click', closeBentoPicker);
    pickerModal.addEventListener('click', (e) => {
        if (e.target === pickerModal) closeBentoPicker();
    });
})();
// ==========================================
// SELECTOR BENTO UI AUTOMÁTICO PARA INPUTS DE MES
// ==========================================
(() => {
    const monthModal = document.getElementById('bento-month-picker-modal');
    const monthGrid = document.getElementById('bento-month-grid');
    const yearLabel = document.getElementById('bento-month-year-label');
    const titleEl = document.getElementById('bento-month-picker-title');
    const clearBtn = document.getElementById('bento-month-clear-btn');

    if (!monthModal || !monthGrid || !yearLabel) return;

    const MONTHS_FULL = [
        'Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
        'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'
    ];
    const MONTHS_SHORT = [
        'Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun',
        'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'
    ];

    let activeMonthInput = null;
    let viewYear = new Date().getFullYear();

    const formatMonthDisplay = (ymValue) => {
        if (!ymValue || !/^\d{4}-\d{2}$/.test(ymValue)) return '';
        const [y, m] = ymValue.split('-');
        const mIdx = parseInt(m, 10) - 1;
        if (mIdx < 0 || mIdx > 11) return ymValue;
        return `${MONTHS_FULL[mIdx]} ${y}`;
    };

    const syncMonthTrigger = (inputEl) => {
        const triggerBtn = inputEl?._bentoMonthTrigger;
        if (!triggerBtn) return;
        const textSpan = triggerBtn.querySelector('.bento-trigger-text');
        const formatted = formatMonthDisplay(inputEl.value);

        if (formatted) {
            textSpan.textContent = formatted;
            textSpan.style.color = 'var(--text-main)';
        } else {
            textSpan.textContent = 'Seleccionar mes...';
            textSpan.style.color = 'var(--text-muted)';
        }
        triggerBtn.style.opacity = inputEl.disabled ? '0.68' : '1';
        triggerBtn.style.pointerEvents = inputEl.disabled ? 'none' : 'auto';
    };

    const renderMonthGrid = () => {
        yearLabel.textContent = String(viewYear);
        const now = new Date();
        const currYear = now.getFullYear();
        const currMonth = now.getMonth();
        const selectedVal = activeMonthInput ? activeMonthInput.value : '';

        monthGrid.innerHTML = MONTHS_SHORT.map((shortName, idx) => {
            const ym = `${viewYear}-${String(idx + 1).padStart(2, '0')}`;
            const isSelected = selectedVal === ym;
            const isCurrent = viewYear === currYear && idx === currMonth;
            return `
                <button type="button"
                    class="bento-month-cell ${isSelected ? 'selected' : ''} ${isCurrent ? 'is-current' : ''}"
                    data-ym="${ym}">
                    ${shortName}
                </button>
            `;
        }).join('');
    };

    const closeMonthPicker = () => {
        monthModal.classList.add('hidden');
        activeMonthInput = null;
    };

    const applyMonthValue = (ymValue) => {
        if (!activeMonthInput) return;
        activeMonthInput.value = ymValue;
        activeMonthInput.dispatchEvent(new Event('input', { bubbles: true }));
        activeMonthInput.dispatchEvent(new Event('change', { bubbles: true }));
        syncMonthTrigger(activeMonthInput);
        closeMonthPicker();
    };

    const openMonthPicker = (inputEl) => {
        activeMonthInput = inputEl;
        const siblingLabel = inputEl.closest('.form-group')?.querySelector('label');
        if (titleEl) {
            titleEl.textContent = siblingLabel ? siblingLabel.textContent.trim() : 'Seleccionar Mes';
        }

        if (inputEl.value && /^\d{4}-\d{2}$/.test(inputEl.value)) {
            viewYear = parseInt(inputEl.value.split('-')[0], 10);
        } else {
            viewYear = new Date().getFullYear();
        }

        if (clearBtn) {
            clearBtn.classList.toggle('hidden', inputEl.dataset.wasRequired === '1');
        }

        renderMonthGrid();
        document.body.appendChild(monthModal);
        monthModal.classList.remove('hidden');
    };

    const upgradeMonthInput = (inputEl) => {
        if (!inputEl || inputEl.dataset.bentoMonthBound === '1') return;
        inputEl.dataset.bentoMonthBound = '1';

        if (inputEl.required) {
            inputEl.dataset.wasRequired = '1';
            inputEl.required = false;
        }

        const triggerBtn = document.createElement('button');
        triggerBtn.type = 'button';
        triggerBtn.className = 'bento-select-trigger bento-month-trigger';
        triggerBtn.setAttribute('aria-haspopup', 'dialog');
        triggerBtn.innerHTML = `
            <span class="bento-trigger-text">Seleccionar mes...</span>
            <svg class="bento-trigger-chevron" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
        `;

        inputEl._bentoMonthTrigger = triggerBtn;
        inputEl.classList.add('hidden');
        inputEl.setAttribute('aria-hidden', 'true');
        inputEl.tabIndex = -1;
        inputEl.parentNode.insertBefore(triggerBtn, inputEl);

        triggerBtn.addEventListener('click', () => openMonthPicker(inputEl));
        inputEl.addEventListener('change', () => syncMonthTrigger(inputEl));
        inputEl.addEventListener('input', () => syncMonthTrigger(inputEl));

        syncMonthTrigger(inputEl);
    };

    // Interceptar asignaciones programáticas de .value en inputs de mes
    const inputValDesc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value');
    if (inputValDesc && inputValDesc.get && inputValDesc.set) {
        Object.defineProperty(HTMLInputElement.prototype, 'value', {
            get() { return inputValDesc.get.call(this); },
            set(val) {
                inputValDesc.set.call(this, val);
                if (this.dataset && this.dataset.bentoMonthBound === '1') {
                    syncMonthTrigger(this);
                }
            }
        });
    }

    document.querySelectorAll('input[type="month"]').forEach(upgradeMonthInput);

    const domObserver = new MutationObserver((mutations) => {
        mutations.forEach(m => {
            m.addedNodes.forEach(node => {
                if (node.nodeType !== 1) return;
                if (node.matches && node.matches('input[type="month"]')) upgradeMonthInput(node);
                node.querySelectorAll?.('input[type="month"]').forEach(upgradeMonthInput);
            });
        });
    });
    domObserver.observe(document.body, { childList: true, subtree: true });

    document.getElementById('bento-month-prev-year')?.addEventListener('click', () => {
        viewYear -= 1;
        renderMonthGrid();
    });
    document.getElementById('bento-month-next-year')?.addEventListener('click', () => {
        viewYear += 1;
        renderMonthGrid();
    });

    monthGrid.addEventListener('click', (e) => {
        const cell = e.target.closest('.bento-month-cell');
        if (cell) applyMonthValue(cell.getAttribute('data-ym'));
    });

    document.getElementById('bento-month-today-btn')?.addEventListener('click', () => {
        const now = new Date();
        const ym = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
        applyMonthValue(ym);
    });

    window.openBentoMonthPicker = openMonthPicker;

    clearBtn?.addEventListener('click', () => applyMonthValue(''));
    document.getElementById('close-bento-month-picker-btn')?.addEventListener('click', closeMonthPicker);
    monthModal.addEventListener('click', (e) => {
        if (e.target === monthModal) closeMonthPicker();
    });
})();
// ============================================================
// FASE 5: REBALANCEO DE SOBREGIROS Y BUSCADOR ARCHIVO INDEXEDDB
// ============================================================

// 1. REBALANCEO EN 1 TOQUE ("CUBRIR SOBREGIRO") EN PRESUPUESTO
const openBudgetRebalanceModal = (preselectedToCat = '') => {
    const monthId = getMonthId(viewDate);
    if (typeof getMonthlyBudgetRebalanceCandidates !== 'function') return;
    const { year, mIdx, overBudgetCats, donorCats } = getMonthlyBudgetRebalanceCandidates(monthId);

    if (overBudgetCats.length === 0 || donorCats.length === 0) {
        alert('No hay categorías sobregiradas o con saldo libre suficiente para rebalancear este mes.');
        return;
    }

    let modalEl = document.getElementById('budget-rebalance-modal');
    if (!modalEl) {
        modalEl = document.createElement('div');
        modalEl.id = 'budget-rebalance-modal';
        modalEl.className = 'modal hidden';
        modalEl.setAttribute('role', 'dialog');
        modalEl.setAttribute('aria-modal', 'true');
        modalEl.style.cssText = 'z-index: 2640; align-items: center; justify-content: center; padding: 16px;';
        document.body.appendChild(modalEl);
        modalEl.addEventListener('click', (ev) => {
            if (ev.target === modalEl) {
                hasUnsavedChanges = false;
                modalEl.classList.add('hidden');
            }
        });
    }

    const esc = window.escapeHtml || ((s) => String(s ?? ''));
    const escA = window.escapeAttr || esc;
    const targetCat = overBudgetCats.find(c => c.name === preselectedToCat) || overBudgetCats[0];
    const defaultDonor = donorCats[0];
    const suggestedAmt = Math.min(targetCat.overrun, defaultDonor.surplus);

    modalEl.innerHTML = `
        <div class="modal-content" style="width:100%; max-width:400px; margin:auto; border-radius:24px; padding:20px 18px; box-shadow:0 20px 45px rgba(0,0,0,0.22); border:1px solid var(--border-color); background:var(--modal-bg);">
            <div class="modal-header" style="margin-bottom:10px;">
                <div>
                    <h3 style="margin:0; font-size:16.5px; font-weight:800;">Cubrir sobregiro</h3>
                    <small style="color:var(--text-muted); font-size:11px;">Ajuste puntual solo para ${esc(formatMonthName(viewDate))}</small>
                </div>
                <button type="button" id="close-budget-rebalance-btn" class="mini-action-btn">Cerrar</button>
            </div>

            <form id="budget-rebalance-form">
                <div class="form-group">
                    <label>Categoría excedida (Recibe cupo)</label>
                    <select id="reb-to-cat">
                        ${overBudgetCats.map(c => `<option value="${escA(c.name)}" ${c.name === targetCat.name ? 'selected' : ''}>${esc(c.label)} (Excedido: ${formatCompact(c.overrun)})</option>`).join('')}
                    </select>
                </div>

                <div class="form-group">
                    <label>Tomar saldo libre de (Cede cupo)</label>
                    <select id="reb-from-cat">
                        ${donorCats.map(c => `<option value="${escA(c.name)}" ${c.name === defaultDonor.name ? 'selected' : ''}>${esc(c.label)} (Libre: ${formatCompact(c.surplus)})</option>`).join('')}
                    </select>
                </div>

                <div class="form-group">
                    <label>Monto a trasladar ($)</label>
                    <input type="text" id="reb-amount-input" class="money-input" inputmode="decimal" value="${formatNumberInput(suggestedAmt)}" required>
                    <small id="reb-preview-hint" style="display:block; font-size:10.5px; color:var(--text-muted); margin-top:5px;">Tu presupuesto global del mes se mantiene exactamente igual.</small>
                </div>

                <button type="submit" class="btn btn-primary" style="width:100%;">Aplicar rebalanceo del mes</button>
            </form>
        </div>
    `;

    modalEl.querySelector('#close-budget-rebalance-btn')?.addEventListener('click', () => {
        hasUnsavedChanges = false;
        modalEl.classList.add('hidden');
    });

    const toSel = modalEl.querySelector('#reb-to-cat');
    const fromSel = modalEl.querySelector('#reb-from-cat');
    const amtInp = modalEl.querySelector('#reb-amount-input');

    const syncSuggestedRebalance = () => {
        const tObj = overBudgetCats.find(c => c.name === toSel?.value) || overBudgetCats[0];
        const fObj = donorCats.find(c => c.name === fromSel?.value) || donorCats[0];
        if (tObj && fObj && amtInp) {
            amtInp.value = formatNumberInput(Math.min(tObj.overrun, fObj.surplus));
        }
    };

    toSel?.addEventListener('change', syncSuggestedRebalance);
    fromSel?.addEventListener('change', syncSuggestedRebalance);
    amtInp?.addEventListener('input', (e) => applyLiveDecimalFormatting(e.target));

    modalEl.querySelector('#budget-rebalance-form')?.addEventListener('submit', (ev) => {
        ev.preventDefault();
        const amt = parseMoneyInput(amtInp?.value);
        const res = applyBudgetRebalanceForMonth({
            fromCatName: fromSel?.value,
            toCatName: toSel?.value,
            amount: amt,
            year,
            monthIndex: mIdx
        });
        if (!res.success) {
            alert(res.reason || 'No se pudo completar el rebalanceo.');
            return;
        }
        hasUnsavedChanges = false;
        modalEl.classList.add('hidden');
        renderBudgetView();
        updateDashboard();
    });

    modalEl.classList.remove('hidden');
};

const renderBudgetRebalanceBanner = () => {
    const listContainer = document.getElementById('budget-categories-list');
    if (!listContainer || typeof getMonthlyBudgetRebalanceCandidates !== 'function') return;

    let banner = document.getElementById('budget-rebalance-banner');
    if (currentBudgetType !== 'expense') {
        banner?.classList.add('hidden');
        return;
    }

    const { overBudgetCats, donorCats } = getMonthlyBudgetRebalanceCandidates(getMonthId(viewDate));
    if (overBudgetCats.length === 0 || donorCats.length === 0) {
        banner?.classList.add('hidden');
        return;
    }

    if (!banner) {
        banner = document.createElement('div');
        banner.id = 'budget-rebalance-banner';
        banner.className = 'glass-sub-box';
        banner.style.cssText = 'margin-bottom:12px; padding:11px 12px; border-color:rgba(245,158,11,0.38); background:rgba(245,158,11,0.08); display:flex; justify-content:space-between; align-items:center; gap:10px;';
        listContainer.insertAdjacentElement('beforebegin', banner);
    }

    const esc = window.escapeHtml || ((s) => String(s ?? ''));
    const topOver = overBudgetCats[0];
    banner.classList.remove('hidden');
    banner.innerHTML = `
        <div style="min-width:0; flex:1;">
            <strong style="display:block; font-size:12px; color:#d97706;">${overBudgetCats.length === 1 ? `Sobregiro en ${esc(topOver.label)}` : `${overBudgetCats.length} categorías sobregiradas`}</strong>
            <small style="display:block; font-size:10.5px; color:var(--text-muted); line-height:1.35;">Cúbrelo moviendo cupo libre de otra categoría sin subir tu tope global.</small>
        </div>
        <button type="button" id="btn-open-budget-rebalance" class="mini-action-btn" style="color:#d97706; border-color:rgba(245,158,11,0.4); background:var(--card-bg); font-weight:800; font-size:11px; padding:6px 10px; flex-shrink:0;">
            Cubrir
        </button>
    `;
    banner.querySelector('#btn-open-budget-rebalance')?.addEventListener('click', () => openBudgetRebalanceModal(topOver.name));
};

const budgetListForRebalance = document.getElementById('budget-categories-list');
if (budgetListForRebalance) {
    new MutationObserver(() => renderBudgetRebalanceBanner()).observe(budgetListForRebalance, { childList: true });
}

// 2. BUSCADOR DE AÑOS ARCHIVADOS EN SOLO LECTURA (INDEXEDDB)
window.openArchiveSearchModal = async () => {
    let modalEl = document.getElementById('archive-search-modal');
    if (!modalEl) {
        modalEl = document.createElement('div');
        modalEl.id = 'archive-search-modal';
        modalEl.className = 'modal hidden';
        modalEl.setAttribute('role', 'dialog');
        modalEl.setAttribute('aria-modal', 'true');
        modalEl.style.cssText = 'z-index: 2630; align-items: center; justify-content: center; padding: 16px;';
        modalEl.innerHTML = `
            <div class="modal-content" style="width:100%; max-width:440px; max-height:86dvh; display:flex; flex-direction:column; margin:auto; border-radius:26px; padding:20px 18px; box-shadow:0 20px 45px rgba(0,0,0,0.22); border:1px solid var(--border-color); background:var(--modal-bg);">
                <div class="modal-header" style="margin-bottom:10px; flex-shrink:0;">
                    <div>
                        <h3 style="margin:0; font-size:16.5px; font-weight:800;">Buscador de Archivo Histórico</h3>
                        <small style="color:var(--text-muted); font-size:11px;">Consulta en solo lectura desde IndexedDB</small>
                    </div>
                    <button type="button" id="close-archive-search-btn" class="mini-action-btn">Cerrar</button>
                </div>

                <div style="flex-shrink:0; margin-bottom:10px;">
                    <div style="position:relative; margin-bottom:10px;">
                        <span style="position:absolute; left:12px; top:50%; transform:translateY(-50%); color:var(--text-muted); display:inline-flex; pointer-events:none;">
                            ${renderIcon('search', 15)}
                        </span>
                        <input type="text" id="archive-search-query" inputmode="search" autocomplete="off" placeholder="Buscar comercio, categoría, #etiqueta o monto..." style="width:100%; min-height:42px; padding:10px 12px 10px 36px; border-radius:14px; border:1px solid var(--border-color); background:var(--card-inner-bg); color:var(--text-main); font-size:16px; box-sizing:border-box; -webkit-appearance:none; appearance:none; outline:none;">
                    </div>
                    <div class="form-row" style="margin-bottom:0;">
                        <div class="form-group" style="margin-bottom:0;">
                            <select id="archive-search-year" aria-label="Filtrar por año archivado">
                                <option value="all">Todos los años</option>
                            </select>
                        </div>
                        <div class="form-group" style="margin-bottom:0;">
                            <select id="archive-search-type" aria-label="Filtrar por tipo">
                                <option value="all">Todos los tipos</option>
                                <option value="expense">Solo gastos</option>
                                <option value="income">Solo ingresos</option>
                                <option value="transfer">Transferencias</option>
                            </select>
                        </div>
                    </div>
                </div>

                <div id="archive-search-summary" style="font-size:11px; color:var(--text-muted); margin-bottom:8px; flex-shrink:0;"></div>
                <div id="archive-search-results" style="flex:1; min-height:120px; overflow-y:auto; display:flex; flex-direction:column; gap:7px; padding-right:2px;"></div>
            </div>
        `;
        document.body.appendChild(modalEl);

        modalEl.addEventListener('click', (ev) => {
            if (ev.target === modalEl) modalEl.classList.add('hidden');
        });
        modalEl.querySelector('#close-archive-search-btn')?.addEventListener('click', () => modalEl.classList.add('hidden'));

        const runArchiveQuery = async () => {
            const sumEl = document.getElementById('archive-search-summary');
            const resEl = document.getElementById('archive-search-results');
            if (!resEl || typeof searchArchivedTransactions !== 'function') return;

            resEl.innerHTML = `<div style="text-align:center; padding:24px 10px; color:var(--text-muted); font-size:12px;">Consultando IndexedDB...</div>`;
            try {
                const qVal = document.getElementById('archive-search-query')?.value || '';
                const yVal = document.getElementById('archive-search-year')?.value || 'all';
                const tVal = document.getElementById('archive-search-type')?.value || 'all';
                const data = await searchArchivedTransactions({ query: qVal, year: yVal, type: tVal });

                const yearSel = document.getElementById('archive-search-year');
                if (yearSel && yearSel.options.length <= 1 && data.yearsAvailable.length > 0) {
                    yearSel.innerHTML = `<option value="all">Todos los años (${data.yearsAvailable.length})</option>`
                        + data.yearsAvailable.map(y => `<option value="${y}">${y}</option>`).join('');
                    yearSel.value = yVal;
                }

                if (data.totalArchivedCount === 0) {
                    if (sumEl) sumEl.textContent = '';
                    resEl.innerHTML = `<div style="text-align:center; padding:26px 12px; color:var(--text-muted); font-size:12.5px; line-height:1.45;">Aún no tienes años archivados en IndexedDB. Cuando ejecutes un <b>Cierre de Año</b>, podrás consultar todo tu histórico aquí sin restaurarlo.</div>`;
                    return;
                }

                if (sumEl) {
                    sumEl.innerHTML = `Encontrados: <b>${data.totalFound}</b> de ${data.totalArchivedCount} • Gastos: <b class="negative">-${formatCompact(data.totalOut)}</b> • Ingresos: <b class="positive">+${formatCompact(data.totalIn)}</b>`;
                }

                if (data.items.length === 0) {
                    resEl.innerHTML = `<div style="text-align:center; padding:24px 10px; color:var(--text-muted); font-size:12.5px;">No hay coincidencias con ese filtro.</div>`;
                    return;
                }

                const esc = window.escapeHtml || ((s) => String(s ?? ''));
                resEl.innerHTML = data.items.map(t => {
                    const sign = t.type === 'income' ? '+' : (t.type === 'expense' ? '-' : '');
                    const cls = t.type === 'income' ? 'positive' : (t.type === 'expense' ? 'negative' : '');
                    const accLbl = stripLeadingEmoji(getAccountObj(t.account).name || '');
                    const catLbl = t.category ? `${cleanCatName(t.category)}${t.subcategory && t.subcategory !== 'General' ? ` (${cleanCatName(t.subcategory)})` : ''}` : 'Transferencia';
                    const yLbl = String(getTxMonthId(t) || '');
                    return `
                        <div class="glass-sub-box" style="margin-bottom:0; padding:10px 11px; display:flex; justify-content:space-between; align-items:center; gap:10px;">
                            <div style="min-width:0; flex:1;">
                                <strong style="display:block; font-size:12.5px; color:var(--text-main); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${esc(stripLeadingEmoji(t.description || catLbl))}</strong>
                                <small style="display:block; font-size:10.5px; color:var(--text-muted);">${esc(catLbl)} • ${esc(accLbl)}</small>
                                <small style="display:block; font-size:10px; color:var(--text-muted);">${esc(yLbl)} • ${esc(t.date || '')}</small>
                            </div>
                            <strong class="${cls} privacy-sensitive" style="font-size:12.5px; white-space:nowrap; flex-shrink:0;">${sign}${formatMoney(t.amount)}</strong>
                        </div>
                    `;
                }).join('');
            } catch (err) {
                const escErr = window.escapeHtml || ((s) => String(s ?? ''));
                resEl.innerHTML = `<div style="text-align:center; padding:20px 10px; color:var(--negative); font-size:12px;">${escErr(err?.message || 'No se pudo leer el archivo histórico.')}</div>`;
            }
        };

        modalEl._runArchiveQuery = runArchiveQuery;
        modalEl.querySelector('#archive-search-query')?.addEventListener('input', runArchiveQuery);
        modalEl.querySelector('#archive-search-year')?.addEventListener('change', runArchiveQuery);
        modalEl.querySelector('#archive-search-type')?.addEventListener('change', runArchiveQuery);
    }

    modalEl.classList.remove('hidden');
    modalEl._runArchiveQuery?.();
};

const injectArchiveSearchButton = () => {
    const archiveBtn = document.getElementById('btn-archive-year');
    if (!archiveBtn || document.getElementById('btn-open-archive-search')) return;

    const searchBtn = document.createElement('button');
    searchBtn.type = 'button';
    searchBtn.id = 'btn-open-archive-search';
    searchBtn.className = 'btn btn-secondary';
    searchBtn.style.cssText = 'width:100%; grid-column:1 / -1; margin-top:10px; min-height:42px; padding:10px 14px; font-size:12.5px; font-weight:700; display:flex; align-items:center; justify-content:center; gap:7px; white-space:nowrap;';
    searchBtn.innerHTML = `${renderIcon('search', 14)}<span>Buscar en años archivados (IndexedDB)</span>`;
    searchBtn.addEventListener('click', () => window.openArchiveSearchModal());

    const rowParent = archiveBtn.closest('.form-row') || archiveBtn.parentElement;
    if (rowParent && rowParent.parentElement) {
        rowParent.insertAdjacentElement('afterend', searchBtn);
    } else {
        archiveBtn.insertAdjacentElement('afterend', searchBtn);
    }
};

injectArchiveSearchButton();
// ============================================================
// FASE 6: COMPRA DE CARTERA, AGENDA ACTIVOS FIJOS Y PAQUETE DIAN
// ============================================================

// 1. SIMULADOR DE COMPRA DE CARTERA CON TUS DEUDAS REALES
window.openPortfolioBuyoutModal = () => {
    if (typeof closeSideDrawer === 'function') closeSideDrawer();
    let modalEl = document.getElementById('portfolio-buyout-modal');
    if (!modalEl) {
        modalEl = document.createElement('div');
        modalEl.id = 'portfolio-buyout-modal';
        modalEl.className = 'modal hidden';
        modalEl.setAttribute('role', 'dialog');
        modalEl.setAttribute('aria-modal', 'true');
        modalEl.style.cssText = 'z-index: 2635;';
        modalEl.innerHTML = `
            <div class="modal-content" style="display:flex; flex-direction:column; overflow:hidden; padding:0;">
                <div class="modal-header" style="align-items:flex-start; gap:10px; padding:18px 18px 12px 18px; margin-bottom:0; border-bottom:1px solid var(--border-color); flex-shrink:0; background:var(--modal-bg); backdrop-filter:none; -webkit-backdrop-filter:none;">
                    <div>
                        <h3 style="margin:0; font-size:17.5px; font-weight:800;">Compra de Cartera</h3>
                        <small style="color:var(--text-muted); font-size:11.5px;">Unifica tus tarjetas y créditos reales y valida si ahorras</small>
                    </div>
                    <button type="button" id="close-portfolio-buyout-btn" class="btn-close-modal" style="flex-shrink:0;">Cerrar</button>
                </div>

                <div id="pbo-scroll-body" style="flex:1; overflow-y:auto; padding:14px 18px 22px 18px; -webkit-overflow-scrolling:touch;">
                    <details class="changelog-accordion" style="margin-bottom:12px; background:rgba(245, 158, 11, 0.08); border:1px solid rgba(245, 158, 11, 0.28); padding:10px 12px; box-shadow:none;">
                        <summary style="font-size:11.5px; font-weight:800; color:#d97706;">
                            <span style="display:inline-flex; align-items:center; gap:6px;">${renderIcon('help', 14)} ¿Cuándo conviene una compra de cartera?</span>
                            <span>▾</span>
                        </summary>
                        <div style="margin-top:8px; padding-top:8px; border-top:1px dashed rgba(245,158,11,0.3); font-size:11px; color:var(--text-muted); line-height:1.45; display:flex; flex-direction:column; gap:5px;">
                            <span>• Un banco suele ofrecerte una <b>tasa más baja</b> para recoger tus tarjetas o créditos, pero a veces te alarga el plazo a 36 o 48 meses haciendo que pagues más intereses en total.</span>
                            <span>• Selecciona aquí tus deudas reales y compara tanto el <b>alivio en cuota mensual</b> como el <b>ahorro neto total</b> (sumando seguros y comisiones).</span>
                        </div>
                    </details>

                    <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:7px;">
                        <strong style="font-size:12px; color:var(--text-main);">1. Selecciona las deudas a recoger</strong>
                        <button type="button" id="btn-pbo-select-all" class="mini-action-btn" style="font-size:10.5px; padding:3px 9px; color:var(--accent); font-weight:700;">Marcar todas</button>
                    </div>
                    <div id="pbo-debts-checklist" style="display:flex; flex-direction:column; gap:7px; margin-bottom:12px;"></div>

                    <div class="glass-sub-box" style="padding:12px; margin-bottom:12px;">
                        <strong style="display:block; font-size:12px; color:var(--text-main); margin-bottom:9px;">2. Condiciones de la oferta bancaria</strong>
                        <div class="form-row" style="margin-bottom:8px;">
                            <div class="form-group" style="margin-bottom:0;">
                                <label style="font-size:10px;">Plazo (meses)</label>
                                <input type="number" id="pbo-months" min="1" max="180" value="24">
                            </div>
                            <div class="form-group" style="margin-bottom:0;">
                                <label style="font-size:10px;">Modalidad tasa</label>
                                <select id="pbo-rate-type">
                                    <option value="annual" selected>% E.A.</option>
                                    <option value="monthly">% M.V.</option>
                                </select>
                            </div>
                        </div>
                        <div class="form-row" style="margin-bottom:8px;">
                            <div class="form-group" style="margin-bottom:0;">
                                <label style="font-size:10px;">Tasa ofrecida (%)</label>
                                <input type="text" id="pbo-rate" inputmode="decimal" placeholder="Ej. 16,5">
                            </div>
                            <div class="form-group" style="margin-bottom:0;">
                                <label style="font-size:10px;">Seguro mensual ($)</label>
                                <input type="text" id="pbo-insurance" class="money-input" inputmode="decimal" placeholder="0,00">
                            </div>
                        </div>
                        <div class="form-group" style="margin-bottom:0;">
                            <label style="font-size:10px;">Comisión / Estudio inicial ($, opcional)</label>
                            <input type="text" id="pbo-fee" class="money-input" inputmode="decimal" placeholder="0,00">
                        </div>
                    </div>

                    <div id="pbo-results-slot"></div>
                </div>
            </div>
        `;
        document.body.appendChild(modalEl);

        modalEl.addEventListener('click', (ev) => {
            if (ev.target === modalEl) { hasUnsavedChanges = false; modalEl.classList.add('hidden'); }
        });
        modalEl.querySelector('#close-portfolio-buyout-btn')?.addEventListener('click', () => {
            hasUnsavedChanges = false;
            modalEl.classList.add('hidden');
        });
    }

    const renderPortfolioBuyoutResults = () => {
        const slot = document.getElementById('pbo-results-slot');
        if (!slot || typeof simulatePortfolioBuyout !== 'function') return;

        const selectedIds = Array.from(document.querySelectorAll('#pbo-debts-checklist .pbo-debt-check:checked')).map(c => c.value);
        const months = parseInt(document.getElementById('pbo-months')?.value, 10) || 24;
        const rateType = document.getElementById('pbo-rate-type')?.value || 'annual';
        const rawRateText = String(document.getElementById('pbo-rate')?.value || '').trim().replace(',', '.');
        const rate = Math.max(0, Math.min(150, parseFloat(rawRateText) || 0));
        const ins = parseMoneyInput(document.getElementById('pbo-insurance')?.value);
        const fee = parseMoneyInput(document.getElementById('pbo-fee')?.value);

        const sim = simulatePortfolioBuyout({
            selectedIds,
            newRate: rate,
            newRateType: rateType,
            newMonths: months,
            monthlyInsurance: ins,
            originationFee: fee
        });

        if (!sim.valid) {
            const escReason = window.escapeHtml || ((s) => String(s ?? ''));
            slot.innerHTML = `<div class="glass-sub-box" style="text-align:center; font-size:12px; color:var(--text-muted); margin-bottom:0;">${escReason(sim.reason)}</div>`;
            return;
        }

        let verdictCls = 'danger';
        let verdictTitle = 'No conviene financieramente';
        let verdictDesc = `Pagarías <b>${formatMoney(Math.abs(sim.totalCostSavings))}</b> adicionales frente a seguir con tus deudas actuales.`;

        if (sim.verdict === 'ideal') {
            verdictCls = 'good';
            verdictTitle = 'Compra de cartera favorable';
            verdictDesc = `Bajas tu cuota en <b>${formatMoney(sim.monthlyCashflowSavings)}/mes</b> y ahorras <b>${formatMoney(sim.totalCostSavings)}</b> en costo total.`;
        } else if (sim.verdict === 'cheaper_higher_quota') {
            verdictCls = 'good';
            verdictTitle = 'Ahorras intereses, con cuota más alta';
            verdictDesc = `Ahorras <b>${formatMoney(sim.totalCostSavings)}</b> en total al acortar plazo, pero tu cuota sube <b>${formatMoney(Math.abs(sim.monthlyCashflowSavings))}/mes</b>.`;
        } else if (sim.verdict === 'cashflow_only') {
            verdictCls = 'warn';
            verdictTitle = 'Alivia flujo mensual, pero cuesta más en total';
            verdictDesc = `Liberas <b>${formatMoney(sim.monthlyCashflowSavings)}/mes</b> en caja, pero al extender a ${sim.newMonths} meses pagarías <b>${formatMoney(Math.abs(sim.totalCostSavings))}</b> extra en intereses/seguros.`;
        }

        slot.innerHTML = `
            <div class="smart-verdict-box ${verdictCls}" style="margin-bottom:10px; padding:12px 13px;">
                <strong style="display:block; font-size:13px; margin-bottom:4px;">${verdictTitle}</strong>
                <span style="font-size:11.5px; color:var(--text-muted); line-height:1.42;">${verdictDesc}</span>
            </div>

            <div class="pbo-compare-grid" style="margin-bottom:10px;">
                <div class="extra-sim-option-card">
                    <span class="extra-sim-tag neutral">Actual (${sim.selectedCount})</span>
                    <small style="font-size:10px; color:var(--text-muted); margin-top:6px;">Cuota mensual combinada</small>
                    <strong style="font-size:14px; color:var(--text-main);">${formatMoney(sim.currentMonthlyQuota)}</strong>
                    <small style="font-size:10px; color:var(--text-muted); margin-top:6px;">Tasa prom.: <b>${String(sim.weightedCurrentEA).replace('.', ',')}% E.A.</b></small>
                    <div style="margin-top:6px; padding-top:6px; border-top:1px dashed var(--border-color); font-size:10.5px;">
                        <span style="color:var(--text-muted); display:block;">Total futuro est.:</span>
                        <strong>${formatMoney(sim.currentTotalCost)}</strong>
                    </div>
                </div>

                <div class="extra-sim-option-card ${sim.totalCostSavings > 0 ? 'is-recommended' : ''}">
                    <span class="extra-sim-tag">Nueva Oferta (${sim.newMonths}m)</span>
                    <small style="font-size:10px; color:var(--text-muted); margin-top:6px;">Nueva cuota mensual</small>
                    <strong class="${sim.monthlyCashflowSavings >= 0 ? 'positive' : 'negative'}" style="font-size:14px;">${formatMoney(sim.newMonthlyQuota)}</strong>
                    <small style="font-size:10px; color:var(--text-muted); margin-top:6px;">Tasa: <b>${String(sim.newEA).replace('.', ',')}% E.A.</b></small>
                    <div style="margin-top:6px; padding-top:6px; border-top:1px dashed var(--border-color); font-size:10.5px;">
                        <span style="color:var(--text-muted); display:block;">Total con seguros/com.:</span>
                        <strong class="${sim.totalCostSavings >= 0 ? 'positive' : 'negative'}">${formatMoney(sim.newTotalCost)}</strong>
                    </div>
                </div>
            </div>

            <button type="button" id="btn-pbo-create-debt" class="btn btn-primary" style="width:100%; font-size:12.5px; padding:11px 14px;">
                Crear crédito con esta compra de cartera (${formatCompact(sim.totalBalance)})
            </button>
        `;

        slot.querySelector('#btn-pbo-create-debt')?.addEventListener('click', () => {
            modalEl.classList.add('hidden');
            if (typeof openCreateDebtWithPreset === 'function') {
                openCreateDebtWithPreset({
                    name: 'Compra de Cartera',
                    principal: sim.totalBalance,
                    periods: sim.newMonths,
                    rate: rate,
                    rateType: rateType,
                    monthlyQuota: sim.newMonthlyQuota
                });
            }
        });
    };

    const debtsList = typeof getRefinanceEligibleDebts === 'function' ? getRefinanceEligibleDebts() : [];
    const listBox = document.getElementById('pbo-debts-checklist');
    if (listBox) {
        const esc = window.escapeHtml || ((s) => String(s ?? ''));
        const escA = window.escapeAttr || esc;
        if (debtsList.length === 0) {
            listBox.innerHTML = `<div class="glass-sub-box" style="text-align:center; font-size:12px; color:var(--text-muted); margin-bottom:0;">No tienes tarjetas ni préstamos con saldo pendiente para unificar.</div>`;
        } else {
            listBox.innerHTML = debtsList.map(d => `
                <label class="pbo-debt-row">
                    <input type="checkbox" class="pbo-debt-check" value="${escA(d.id)}" checked>
                    <div style="flex:1; min-width:0;">
                        <strong style="display:block; font-size:12.5px; color:var(--text-main); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${esc(d.name)}</strong>
                        <small style="display:block; font-size:10.5px; color:var(--text-muted);">Cuota: ${formatCompact(d.currentQuota)}/m • ${d.eaRate > 0 ? `${String(d.eaRate).replace('.', ',')}% E.A.` : '0% tasa'}</small>
                    </div>
                    <strong class="negative privacy-sensitive" style="font-size:12.5px; white-space:nowrap;">${formatCompact(d.balance)}</strong>
                </label>
            `).join('');
            listBox.querySelectorAll('.pbo-debt-check').forEach(chk => chk.addEventListener('change', renderPortfolioBuyoutResults));
        }
    }

    const selectAllBtn = document.getElementById('btn-pbo-select-all');
    if (selectAllBtn) {
        selectAllBtn.onclick = () => {
            const checks = Array.from(document.querySelectorAll('#pbo-debts-checklist .pbo-debt-check'));
            const allChecked = checks.every(c => c.checked);
            checks.forEach(c => { c.checked = !allChecked; });
            selectAllBtn.textContent = allChecked ? 'Marcar todas' : 'Desmarcar';
            renderPortfolioBuyoutResults();
        };
    }

    ['#pbo-months', '#pbo-rate-type', '#pbo-rate', '#pbo-insurance', '#pbo-fee'].forEach(sel => {
        const el = modalEl.querySelector(sel);
        if (el) {
            el.oninput = (e) => {
                if (el.classList.contains('money-input')) applyLiveDecimalFormatting(e.target);
                renderPortfolioBuyoutResults();
            };
            el.onchange = renderPortfolioBuyoutResults;
        }
    });

    hasUnsavedChanges = false;
    modalEl.classList.remove('hidden');
    renderPortfolioBuyoutResults();
};

const injectPortfolioBuyoutEntryPoints = () => {
    // 1. En el menú lateral > Asesores Inteligentes
    const compareBtn = document.getElementById('drawer-credit-compare');
    if (compareBtn && !document.getElementById('drawer-portfolio-buyout')) {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.id = 'drawer-portfolio-buyout';
        btn.className = 'drawer-sub-item';
        btn.innerHTML = `
            <span class="drawer-icon-box" style="background:rgba(14, 165, 233, 0.14); color:#0ea5e9;">${renderIcon('repeat', 15)}</span>
            <span>Compra de Cartera</span>
        `;
        btn.addEventListener('click', () => {
            if (typeof closeSideDrawer === 'function') closeSideDrawer();
            if (typeof attemptCloseModals === 'function' && attemptCloseModals()) {
                window.openPortfolioBuyoutModal();
            }
        });
        compareBtn.insertAdjacentElement('afterend', btn);
    }

    // 2. Acceso rápido a ancho completo debajo del resumen de Deuda Vigente
    const plannerBtn = document.getElementById('open-debt-planner-btn');
    if (plannerBtn && !document.getElementById('open-portfolio-buyout-from-debts')) {
        const quickBtn = document.createElement('button');
        quickBtn.type = 'button';
        quickBtn.id = 'open-portfolio-buyout-from-debts';
        quickBtn.className = 'btn btn-secondary';
        quickBtn.style.cssText = 'width:100%; margin: -4px 0 12px 0; min-height:40px; padding:9px 14px; border-radius:14px; font-size:12.5px; font-weight:700; display:flex; align-items:center; justify-content:center; gap:7px;';
        quickBtn.innerHTML = `${renderIcon('refresh', 14)}<span>Simular Compra de Cartera</span>`;
        quickBtn.addEventListener('click', () => window.openPortfolioBuyoutModal());

        const summaryBox = plannerBtn.closest('.budget-summary-box, .reconcile-box, .glass-sub-box') || plannerBtn.parentElement;
        if (summaryBox && summaryBox !== plannerBtn) {
            summaryBox.insertAdjacentElement('afterend', quickBtn);
        } else {
            plannerBtn.insertAdjacentElement('afterend', quickBtn);
        }
    }
};

injectPortfolioBuyoutEntryPoints();
setTimeout(injectPortfolioBuyoutEntryPoints, 450);

// 2. AGENDA DE OBLIGACIONES ANUALES EN ACTIVOS FIJOS (SOAT, TECNO, PREDIAL, VEHICULAR)
const renderAssetAnnualObligationsUI = (asset) => {
    const histList = document.getElementById('asset-history-list');
    if (!histList || !asset || typeof computeAssetObligationMetrics !== 'function') return;

    let box = document.getElementById('asset-annual-obligations-box');
    if (!box) {
        box = document.createElement('div');
        box.id = 'asset-annual-obligations-box';
        box.className = 'glass-sub-box';
        box.style.cssText = 'margin:12px 0; padding:12px 13px; border-color:var(--accent-border);';
        const histAnchor = histList.previousElementSibling || histList;
        histAnchor.insertAdjacentElement('beforebegin', box);
    }

    if (asset.status !== 'active') {
        box.classList.add('hidden');
        return;
    }

    box.classList.remove('hidden');
    if (!Array.isArray(asset.annualObligations)) asset.annualObligations = [];

    const esc = window.escapeHtml || ((s) => String(s ?? ''));
    const escA = window.escapeAttr || esc;
    const enriched = asset.annualObligations.map(ob => ({ ob, m: computeAssetObligationMetrics(ob) }))
        .sort((a, b) => (a.m.daysToDue ?? 9999) - (b.m.daysToDue ?? 9999));

    const totalAnnualCost = round2(enriched.reduce((s, x) => s + x.m.effectiveTargetAmount, 0));
    const totalMonthlyReserve = round2(enriched.reduce((s, x) => s + x.m.suggestedMonthlySave, 0));
    const nextYearStr = `${currentDate.getFullYear() + 1}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(Math.min(28, currentDate.getDate())).padStart(2, '0')}`;

    const presets = [
        { label: 'SOAT', hint: 750000 },
        { label: 'Tecnomecánica', hint: 320000 },
        { label: 'Imp. Vehicular', hint: 950000 },
        { label: 'Imp. Predial', hint: 1200000 },
        { label: 'Seguro Todo Riesgo', hint: 1800000 }
    ];

    const availablePockets = (financeData.pockets || []).filter(p => p.id !== 'Pocket_Monedas');
    const linkedPocketObj = asset.linkedPocketId
        ? availablePockets.find(p => String(p.id) === String(asset.linkedPocketId))
        : null;

    const inferAssetExpenseCategory = () => {
        const expCats = (financeData.categories?.expense || []).filter(c => !c.isArchived);
        const isVehicle = /veh[ií]culo|carro|moto|auto/i.test(`${asset.category || ''} ${asset.name || ''}`);
        const isHome = /inmueble|vivienda|casa|apto|apartamento/i.test(`${asset.category || ''} ${asset.name || ''}`);
        if (isVehicle) {
            const c = expCats.find(x => /transporte|veh[ií]culo|moto|carro/i.test(x.name));
            if (c) return c.name;
        }
        if (isHome) {
            const c = expCats.find(x => /vivienda|hogar|servicios/i.test(x.name));
            if (c) return c.name;
        }
        return expCats.find(x => /otros gastos/i.test(x.name))?.name || expCats[0]?.name || 'Otros Gastos';
    };

    const syncObligationToRecurring = (ob, mInfo) => {
        if (!Array.isArray(financeData.subscriptions)) financeData.subscriptions = [];
        const existingSub = ob.linkedSubscriptionId
            ? financeData.subscriptions.find(s => String(s.id) === String(ob.linkedSubscriptionId))
            : null;
        const catName = ob.category || inferAssetExpenseCategory();
        const subLabel = `${ob.label} (${stripLeadingEmoji(asset.name)})`;
        const targetAmt = mInfo ? mInfo.effectiveTargetAmount : round2(ob.estimatedAmount || 0);

        if (existingSub) {
            existingSub.name = subLabel;
            existingSub.amount = targetAmt;
            existingSub.cycle = 'annual';
            existingSub.nextBillingDate = ob.dueDate || existingSub.nextBillingDate;
            existingSub.category = catName;
            existingSub.status = 'active';
            existingSub.linkedAssetId = asset.id;
            existingSub.linkedObligationId = ob.id;
            return existingSub;
        }

        const newSub = {
            id: `Sub_Asset_${Date.now()}_${Math.floor(Math.random() * 100)}`,
            name: subLabel,
            amount: targetAmt,
            currency: 'COP',
            cycle: 'annual',
            nextBillingDate: ob.dueDate || nextYearStr,
            accountId: getDefaultAccountId(false),
            category: catName,
            subcategory: 'General',
            reserveInBudget: false,
            prorateMode: 'monthly',
            reminderDays: 15,
            status: 'active',
            lastPaidMonthId: '',
            linkedAssetId: asset.id,
            linkedObligationId: ob.id
        };
        financeData.subscriptions.push(newSub);
        ob.linkedSubscriptionId = newSub.id;
        return newSub;
    };

    const listHtml = enriched.length === 0
        ? `<small style="display:block; font-size:11px; color:var(--text-muted); padding:6px 0;">Agenda aquí el SOAT, tecnomecánica, predial o seguro para calcular cuánto apartar y sincronizar con Recurrentes.</small>`
        : enriched.map(({ ob, m }) => {
            let badgeCls = 'neutral';
            let badgeTxt = m.daysToDue !== null ? `En ${m.daysToDue}d` : 'Programado';
            if (m.status === 'paid') { badgeCls = 'good'; badgeTxt = `Pagado ${m.dueYear}`; }
            else if (m.status === 'overdue') { badgeCls = 'danger'; badgeTxt = `Venció hace ${Math.abs(m.daysToDue)}d`; }
            else if (m.status === 'urgent') { badgeCls = 'danger'; badgeTxt = m.daysToDue === 0 ? 'Vence hoy' : `En ${m.daysToDue}d`; }
            else if (m.status === 'soon') { badgeCls = 'warn'; badgeTxt = `En ${m.daysToDue}d`; }

            const linkedSub = ob.linkedSubscriptionId
                ? (financeData.subscriptions || []).find(s => String(s.id) === String(ob.linkedSubscriptionId))
                : null;
            const recBadge = linkedSub
                ? `<span style="font-size:9.5px; font-weight:700; color:var(--accent); background:var(--accent-soft); padding:1px 6px; border-radius:99px;">↻ Recurrente</span>`
                : '';

            const discLine = m.hasActiveDiscount
                ? `<small style="display:block; font-size:10px; color:var(--positive); font-weight:700;">Pronto pago (-${m.discPct}%): hasta ${esc(ob.discountDate)} • Ahorras ${formatCompact(m.discSaving)}</small>`
                : '';

            return `
                <div class="asset-ob-row">
                    <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:8px; margin-bottom:4px;">
                        <div style="min-width:0; flex:1;">
                            <div style="display:flex; align-items:center; gap:6px; flex-wrap:wrap;">
                                <strong style="font-size:12.5px; color:var(--text-main);">${esc(ob.label)}</strong>
                                ${recBadge}
                            </div>
                            <small style="display:block; font-size:10.5px; color:var(--text-muted);">Límite: ${esc(ob.dueDate || 'Sin fecha')} • ${formatMoney(m.effectiveTargetAmount)}</small>
                            ${discLine}
                        </div>
                        <span class="widget-badge ${badgeCls}" style="font-size:9.5px; padding:2px 7px; flex-shrink:0;">${badgeTxt}</span>
                    </div>
                    <div style="display:flex; justify-content:space-between; align-items:center; gap:6px; margin-top:6px;">
                        <small style="font-size:10.5px; color:var(--accent); font-weight:700;">
                            ${m.isPaidForYear ? 'Al día este periodo' : `Apartar ${formatCompact(m.suggestedMonthlySave)}/mes (${m.monthsLeft}m)`}
                        </small>
                        <div style="display:flex; gap:5px;">
                            ${!linkedSub ? `<button type="button" class="mini-action-btn asset-ob-link-rec-btn" data-ob-id="${escA(ob.id)}" title="Sincronizar con Pagos Recurrentes" style="font-size:10px; padding:3px 7px; color:var(--accent);">↻ Rec.</button>` : ''}
                            <button type="button" class="mini-action-btn asset-ob-edit-btn" data-ob-id="${escA(ob.id)}" title="Editar obligación" style="font-size:10px; padding:3px 7px; color:var(--text-main);">Editar</button>
                            <button type="button" class="mini-action-btn asset-ob-pay-btn" data-ob-id="${escA(ob.id)}" style="font-size:10px; padding:3px 8px; color:var(--positive); font-weight:700;">${m.isPaidForYear ? 'Renovar' : 'Pagar'}</button>
                            <button type="button" class="mini-action-btn asset-ob-del-btn" data-ob-id="${escA(ob.id)}" style="font-size:10px; padding:3px 7px; color:var(--negative);">✕</button>
                        </div>
                    </div>
                </div>
            `;
        }).join('');

    const pocketLinkSectionHtml = enriched.length > 0 ? `
        <div style="padding:9px 10px; border-radius:11px; background:var(--card-bg); border:1px solid var(--border-color); margin-bottom:9px;">
            <label style="display:block; font-size:10px; font-weight:800; color:var(--text-muted); text-transform:uppercase; margin-bottom:5px;">Bolsillo de reserva vinculado</label>
            <div style="display:flex; gap:6px; align-items:center;">
                <select id="asset-ob-pocket-select" aria-label="Bolsillo de reserva vinculado" style="flex:1; min-width:0; font-size:16px; min-height:38px; padding:6px 8px;">
                    <option value="">Sin bolsillo vinculado</option>
                    ${availablePockets.map(p => {
                        const bal = round2((p.principal || 0) + (p.yields || 0));
                        return `<option value="${escA(p.id)}" ${linkedPocketObj && String(linkedPocketObj.id) === String(p.id) ? 'selected' : ''}>${esc(stripLeadingEmoji(p.name))} (${formatCompact(bal)})</option>`;
                    }).join('')}
                    <option value="__create_new__">+ Crear nuevo bolsillo para ${esc(stripLeadingEmoji(asset.name))}</option>
                </select>
                ${linkedPocketObj && totalAnnualCost > 0 ? `<button type="button" id="btn-asset-sync-pocket-meta" class="mini-action-btn" title="Actualizar meta y cuota del bolsillo con estas obligaciones" style="font-size:10.5px; padding:6px 9px; color:var(--accent); font-weight:800; flex-shrink:0;">Ajustar meta</button>` : ''}
            </div>
            ${linkedPocketObj ? `<small style="display:block; font-size:10px; color:var(--text-muted); margin-top:4px;">Vinculado a <b>${esc(stripLeadingEmoji(linkedPocketObj.name))}</b> (Meta actual: ${formatCompact(linkedPocketObj.goal || 0)}). Al pagar, se sugerirá usar este bolsillo si tiene saldo.</small>` : ''}
        </div>
    ` : '';

    box.innerHTML = `
        <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; margin-bottom:8px;">
            <div>
                <strong style="display:flex; align-items:center; gap:6px; font-size:13px; color:var(--text-main);">
                    <span style="color:var(--accent); display:inline-flex;">${renderIcon('calendar', 14)}</span>
                    <span>Obligaciones Anuales</span>
                </strong>
                <small style="font-size:10.5px; color:var(--text-muted);">
                    ${enriched.length > 0 ? `Total anual: ${formatCompact(totalAnnualCost)} • Sugerido: ${formatCompact(totalMonthlyReserve)}/mes` : 'SOAT, Tecnomecánica, Predial y Seguros'}
                </small>
            </div>
        </div>

        ${pocketLinkSectionHtml}
        <div style="display:flex; flex-direction:column; gap:7px; margin-bottom:8px;">${listHtml}</div>

        <details id="asset-ob-add-details" class="changelog-accordion" style="margin-bottom:0; padding:9px 10px; background:var(--card-bg);">
            <summary style="font-size:11.5px; font-weight:800; color:var(--accent);">
                <span>+ Agendar obligación anual</span>
                <span>▾</span>
            </summary>
            <div style="margin-top:9px; padding-top:9px; border-top:1px dashed var(--border-color);">
                <div style="display:flex; flex-wrap:wrap; gap:5px; margin-bottom:8px;">
                    ${presets.map(p => `<button type="button" class="pill-btn asset-ob-preset-btn" data-ob-label="${escA(p.label)}" data-ob-amt="${p.hint}" style="font-size:10px; padding:3px 8px;">${esc(p.label)}</button>`).join('')}
                </div>
                <div class="form-row" style="margin-bottom:7px;">
                    <div class="form-group" style="margin-bottom:0;">
                        <label style="font-size:10px;">Concepto</label>
                        <input type="text" id="asset-ob-label-inp" placeholder="Ej. SOAT">
                    </div>
                    <div class="form-group" style="margin-bottom:0;">
                        <label style="font-size:10px;">Valor estimado ($)</label>
                        <input type="text" id="asset-ob-amt-inp" class="money-input" inputmode="decimal" placeholder="0,00">
                    </div>
                </div>
                <div class="form-row" style="margin-bottom:7px;">
                    <div class="form-group" style="margin-bottom:0;">
                        <label style="font-size:10px;">Fecha vencimiento</label>
                        <input type="date" id="asset-ob-due-inp" value="${nextYearStr}">
                    </div>
                    <div class="form-group" style="margin-bottom:0;">
                        <label style="font-size:10px;">Pronto pago (opc.)</label>
                        <input type="date" id="asset-ob-disc-date-inp">
                    </div>
                </div>
                <div class="form-group" style="margin-bottom:8px;">
                    <label style="font-size:10px;">% Descuento pronto pago (opcional)</label>
                    <input type="number" id="asset-ob-disc-pct-inp" min="0" max="50" step="0.5" placeholder="Ej. 10">
                </div>
                <div class="switch-row" style="margin-bottom:9px; padding:8px 10px;">
                    <div>
                        <strong style="font-size:11.5px;">Sincronizar con Recurrentes (Anual)</strong>
                        <small style="font-size:10px;">Aparecerá en alertas, proyección de caja y sugerencias de +</small>
                    </div>
                    <label class="switch" style="margin:0;"><input type="checkbox" id="asset-ob-sync-rec-check" checked><span class="slider"></span></label>
                </div>
                <button type="button" id="btn-save-asset-obligation" class="btn btn-primary" style="width:100%; padding:9px 12px; font-size:12px;">Guardar en Agenda</button>
            </div>
        </details>
    `;

    const pocketSel = box.querySelector('#asset-ob-pocket-select');
    pocketSel?.addEventListener('change', () => {
        const chosen = pocketSel.value;
        if (chosen === '__create_new__') {
            const earliestDue = enriched.find(x => !x.m.isPaidForYear)?.ob?.dueDate || nextYearStr;
            const newId = `Pocket_Asset_${asset.id}_${Date.now()}`;
            const p = {
                id: newId,
                name: `Reserva ${stripLeadingEmoji(asset.name)}`,
                entity: 'Obligaciones anuales',
                goal: totalAnnualCost,
                startDate: currentDate.toLocaleDateString('en-CA'),
                targetDate: earliestDue,
                customQuota: totalMonthlyReserve,
                principal: 0,
                yields: 0,
                excludeFromBalance: false
            };
            financeData.pockets.push(p);
            asset.linkedPocketId = newId;
            localStorage.setItem('myFinances', JSON.stringify(financeData));
            updateDashboard();
            renderAssetAnnualObligationsUI(asset);
            alert(`Bolsillo "${p.name}" creado y vinculado.`);
        } else {
            asset.linkedPocketId = chosen || null;
            localStorage.setItem('myFinances', JSON.stringify(financeData));
            renderAssetAnnualObligationsUI(asset);
        }
    });

    box.querySelector('#btn-asset-sync-pocket-meta')?.addEventListener('click', () => {
        if (!linkedPocketObj) return;
        const earliestDue = enriched.find(x => !x.m.isPaidForYear)?.ob?.dueDate || nextYearStr;
        linkedPocketObj.goal = totalAnnualCost;
        linkedPocketObj.customQuota = totalMonthlyReserve;
        if (earliestDue) linkedPocketObj.targetDate = earliestDue;
        localStorage.setItem('myFinances', JSON.stringify(financeData));
        updateDashboard();
        renderAssetAnnualObligationsUI(asset);
        alert(`Meta de "${stripLeadingEmoji(linkedPocketObj.name)}" actualizada a ${formatMoney(totalAnnualCost)} (${formatMoney(totalMonthlyReserve)}/mes).`);
    });

    const labelInp = box.querySelector('#asset-ob-label-inp');
    const amtInp = box.querySelector('#asset-ob-amt-inp');
    amtInp?.addEventListener('input', (e) => applyLiveDecimalFormatting(e.target));

    box.querySelectorAll('.asset-ob-preset-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            if (labelInp) labelInp.value = btn.getAttribute('data-ob-label') || '';
            const hint = parseFloat(btn.getAttribute('data-ob-amt')) || 0;
            if (amtInp && hint > 0 && !parseMoneyInput(amtInp.value)) {
                amtInp.value = formatNumberInput(hint);
            }
        });
    });

    let editingObId = null;
    const addDetailsEl = box.querySelector('#asset-ob-add-details');
    const saveObBtn = box.querySelector('#btn-save-asset-obligation');

    box.querySelectorAll('.asset-ob-edit-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            const ob = asset.annualObligations.find(x => String(x.id) === String(btn.getAttribute('data-ob-id')));
            if (!ob) return;
            editingObId = ob.id;
            if (labelInp) labelInp.value = ob.label || '';
            if (amtInp) amtInp.value = ob.estimatedAmount > 0 ? formatNumberInput(ob.estimatedAmount) : '';
            if (box.querySelector('#asset-ob-due-inp')) box.querySelector('#asset-ob-due-inp').value = ob.dueDate || nextYearStr;
            if (box.querySelector('#asset-ob-disc-date-inp')) box.querySelector('#asset-ob-disc-date-inp').value = ob.discountDate || '';
            if (box.querySelector('#asset-ob-disc-pct-inp')) box.querySelector('#asset-ob-disc-pct-inp').value = ob.discountPct > 0 ? ob.discountPct : '';
            if (box.querySelector('#asset-ob-sync-rec-check')) box.querySelector('#asset-ob-sync-rec-check').checked = !!ob.linkedSubscriptionId;
            if (saveObBtn) saveObBtn.textContent = 'Actualizar Obligación';
            if (addDetailsEl) {
                addDetailsEl.open = true;
                addDetailsEl.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
            }
        });
    });

    saveObBtn?.addEventListener('click', () => {
        const label = (labelInp?.value || '').trim();
        const estAmt = parseMoneyInput(amtInp?.value);
        const dueDate = box.querySelector('#asset-ob-due-inp')?.value || '';
        const discountDate = box.querySelector('#asset-ob-disc-date-inp')?.value || '';
        const discountPct = parseFloat(box.querySelector('#asset-ob-disc-pct-inp')?.value) || 0;
        const wantsRecurring = !!box.querySelector('#asset-ob-sync-rec-check')?.checked;

        if (!label || estAmt <= 0 || !dueDate) {
            alert('Completa el concepto, valor estimado y fecha de vencimiento.');
            return;
        }

        const existingOb = editingObId
            ? asset.annualObligations.find(x => String(x.id) === String(editingObId))
            : null;

        let targetOb = existingOb;
        if (existingOb) {
            existingOb.label = label;
            existingOb.estimatedAmount = estAmt;
            existingOb.dueDate = dueDate;
            existingOb.discountDate = discountDate;
            existingOb.discountPct = Math.max(0, Math.min(50, discountPct));
            if (!wantsRecurring && existingOb.linkedSubscriptionId && Array.isArray(financeData.subscriptions)) {
                financeData.subscriptions = financeData.subscriptions.filter(s => String(s.id) !== String(existingOb.linkedSubscriptionId));
                existingOb.linkedSubscriptionId = null;
            }
        } else {
            targetOb = {
                id: `ob_${Date.now()}`,
                label,
                estimatedAmount: estAmt,
                dueDate,
                discountDate,
                discountPct: Math.max(0, Math.min(50, discountPct)),
                category: inferAssetExpenseCategory(),
                lastPaidYear: null,
                linkedSubscriptionId: null
            };
            asset.annualObligations.push(targetOb);
        }

        if (wantsRecurring && targetOb) {
            syncObligationToRecurring(targetOb, computeAssetObligationMetrics(targetOb));
        }

        editingObId = null;
        localStorage.setItem('myFinances', JSON.stringify(financeData));
        hasUnsavedChanges = false;
        if (typeof renderSubscriptionsView === 'function') renderSubscriptionsView();
        updateDashboard();
        renderAssetAnnualObligationsUI(asset);
    });

    box.querySelectorAll('.asset-ob-link-rec-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            const ob = asset.annualObligations.find(x => String(x.id) === String(btn.getAttribute('data-ob-id')));
            if (!ob) return;
            syncObligationToRecurring(ob, computeAssetObligationMetrics(ob));
            localStorage.setItem('myFinances', JSON.stringify(financeData));
            if (typeof renderSubscriptionsView === 'function') renderSubscriptionsView();
            updateDashboard();
            renderAssetAnnualObligationsUI(asset);
        });
    });

    box.querySelectorAll('.asset-ob-del-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            const obId = btn.getAttribute('data-ob-id');
            const targetOb = asset.annualObligations.find(x => String(x.id) === String(obId));
            if (!targetOb) return;
            const execObDel = () => {
                if (targetOb.linkedSubscriptionId && Array.isArray(financeData.subscriptions)) {
                    financeData.subscriptions = financeData.subscriptions.filter(s => String(s.id) !== String(targetOb.linkedSubscriptionId));
                }
                asset.annualObligations = asset.annualObligations.filter(x => String(x.id) !== String(obId));
                localStorage.setItem('myFinances', JSON.stringify(financeData));
                if (typeof renderSubscriptionsView === 'function') renderSubscriptionsView();
                updateDashboard();
                renderAssetAnnualObligationsUI(asset);
            };
            if (typeof window.openBentoConfirmModal === 'function') {
                window.openBentoConfirmModal({
                    title: 'Eliminar obligación anual',
                    subtitle: targetOb.label,
                    message: `¿Eliminar <b>${esc(targetOb.label)}</b> de la agenda de este activo${targetOb.linkedSubscriptionId ? ' y su recordatorio en Recurrentes' : ''}?`,
                    confirmText: 'Eliminar',
                    cancelText: 'Cancelar',
                    danger: true,
                    onConfirm: execObDel
                });
            } else if (confirm(`¿Eliminar ${targetOb.label}?`)) {
                execObDel();
            }
        });
    });

    box.querySelectorAll('.asset-ob-pay-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            const ob = asset.annualObligations.find(x => String(x.id) === String(btn.getAttribute('data-ob-id')));
            if (!ob) return;
            const m = computeAssetObligationMetrics(ob);
            if (m.isPaidForYear) {
                if (/^\d{4}-\d{2}-\d{2}$/.test(ob.dueDate || '')) {
                    const [y, mo, d] = ob.dueDate.split('-').map(Number);
                    ob.dueDate = `${y + 1}-${String(mo).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
                }
                if (/^\d{4}-\d{2}-\d{2}$/.test(ob.discountDate || '')) {
                    const [y, mo, d] = ob.discountDate.split('-').map(Number);
                    ob.discountDate = `${y + 1}-${String(mo).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
                }
                ob.lastPaidYear = null;
                if (ob.linkedSubscriptionId) {
                    const sub = (financeData.subscriptions || []).find(s => String(s.id) === String(ob.linkedSubscriptionId));
                    if (sub && ob.dueDate) sub.nextBillingDate = ob.dueDate;
                }
                localStorage.setItem('myFinances', JSON.stringify(financeData));
                renderAssetAnnualObligationsUI(asset);
                return;
            }

            // Abrir OmniModal sin marcar como pagado todavía; se consolida al guardar el gasto real
            const pBal = linkedPocketObj ? round2((linkedPocketObj.principal || 0) + (linkedPocketObj.yields || 0)) : 0;
            const suggestedAcc = (linkedPocketObj && pBal >= m.effectiveTargetAmount)
                ? linkedPocketObj.id
                : getDefaultAccountId(false);
            const catStr = `${ob.category || inferAssetExpenseCategory()}::General`;

            if (typeof openOmniModal === 'function') {
                openOmniModal({
                    type: 'expense',
                    title: `Pagar ${ob.label}`,
                    amount: m.effectiveTargetAmount,
                    account: suggestedAcc,
                    category: catStr,
                    description: `${ob.label} (${stripLeadingEmoji(asset.name)})`,
                    subscriptionId: ob.linkedSubscriptionId || null,
                    assetObligationContext: { assetId: asset.id, obId: ob.id, dueYear: m.dueYear }
                });
            }
        });
    });
};

// 3. EXPORTACIÓN CIFRADA (.LUMEN-CSV) Y DESCIFRADO A EXCEL DEL "PAQUETE PARA EL CONTADOR"
const triggerLocalFileDownload = (content, fileName, mimeType) => {
    const safeName = window.LumenSecurity?.sanitizeFileName
        ? window.LumenSecurity.sanitizeFileName(fileName, 'Paquete_Contador_Lumen.csv')
        : fileName;
    const blob = new Blob([content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = safeName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
};

window.exportAccountantDianPackageCsv = async (targetYearInput = null, { encrypted = true } = {}) => {
    if (window.LumenSecurity?.isVaultLocked?.()) {
        alert('Debes desbloquear la aplicación antes de exportar el paquete tributario.');
        return;
    }
    if (typeof buildAccountantTaxPackageData !== 'function' || typeof formatAccountantPackageToCsv !== 'function') return;
    const year = parseInt(targetYearInput || document.getElementById('param-tax-year')?.value, 10) || currentDate.getFullYear();

    try {
        const pkg = await buildAccountantTaxPackageData(year);
        const csvContent = formatAccountantPackageToCsv(pkg);
        const plainFileName = `Paquete_Contador_DIAN_${year}_Lumen.csv`;

        if (encrypted && typeof encryptTextPayloadAesGcm === 'function' && typeof window.openLumenBackupPasswordModal === 'function') {
            const password = await window.openLumenBackupPasswordModal({
                mode: 'export',
                title: `Cifrar Paquete Contador ${year}`,
                description: 'Crea una contraseña de al menos 6 caracteres para cifrar tu archivo <b>.lumen-csv</b>. Podrás desbloquearlo a Excel en cualquier momento desde Lumen.',
                labelText: 'Contraseña del reporte',
                submitText: 'Cifrar y descargar'
            });
            if (!password) return;

            const encryptedPayload = await encryptTextPayloadAesGcm(csvContent, password, { year, fileName: plainFileName });
            triggerLocalFileDownload(encryptedPayload, `Paquete_Contador_DIAN_${year}_Lumen.lumen-csv`, 'application/octet-stream');

            const toast = document.createElement('div');
            toast.className = 'sw-toast';
            toast.style.gap = '7px';
            toast.innerHTML = `${renderIcon('lock', 15)}<span>Paquete cifrado ${year} exportado (${pkg.txCount} mov.)</span>`;
            document.body.appendChild(toast);
            setTimeout(() => toast.remove(), 2800);
            return;
        }

        triggerLocalFileDownload(csvContent, plainFileName, 'text/csv;charset=utf-8;');
        const toast = document.createElement('div');
        toast.className = 'sw-toast';
        toast.style.gap = '7px';
        toast.innerHTML = `${renderIcon('check', 15)}<span>Paquete Contador ${year} exportado (${pkg.txCount} mov.)</span>`;
        document.body.appendChild(toast);
        setTimeout(() => toast.remove(), 2800);
    } catch (err) {
        alert(err?.message || 'No se pudo generar el Paquete para el Contador.');
    }
};

window.decryptAccountantLumenCsvFile = async (file) => {
    if (!file || typeof decryptTextPayloadAesGcm !== 'function' || typeof window.openLumenBackupPasswordModal !== 'function') return;
    try {
        if (file.size > 15 * 1024 * 1024) {
            alert('El archivo supera el tamaño máximo seguro (15 MB).');
            return;
        }
        const rawText = await file.text();
        const password = await window.openLumenBackupPasswordModal({
            mode: 'import',
            fileName: file.name,
            title: 'Desbloquear CSV cifrado',
            description: `Ingresa la contraseña con la que protegiste <b>${(window.escapeHtml || String)(file.name)}</b> para descargar el <b>.CSV</b> listo para Excel.`,
            labelText: 'Contraseña del archivo',
            submitText: 'Desbloquear .CSV'
        });
        if (!password) return;

        const { text, meta } = await decryptTextPayloadAesGcm(rawText, password);
        const outName = meta?.fileName || file.name.replace(/\.lumen-csv$/i, '.csv');
        triggerLocalFileDownload(text, outName.endsWith('.csv') ? outName : `${outName}.csv`, 'text/csv;charset=utf-8;');

        const toast = document.createElement('div');
        toast.className = 'sw-toast';
        toast.style.gap = '7px';
        toast.innerHTML = `${renderIcon('check', 15)}<span>CSV descifrado listo para Excel</span>`;
        document.body.appendChild(toast);
        setTimeout(() => toast.remove(), 2800);
    } catch (err) {
        alert(err?.message || 'Contraseña incorrecta o archivo .lumen-csv inválido.');
    }
};

const injectAccountantPackageCard = () => {
    const anchor = document.getElementById('interannual-tax-comp-box') || document.getElementById('renta-proj-details');
    if (!anchor) return;

    let card = document.getElementById('accountant-export-card');
    if (!card) {
        card = document.createElement('div');
        card.id = 'accountant-export-card';
        card.className = 'glass-sub-box';
        card.style.cssText = 'margin-top:12px; padding:13px; border-color:var(--accent-border); background:var(--card-inner-bg);';
        anchor.insertAdjacentElement('afterend', card);
    }

    const activeYear = parseInt(document.getElementById('param-tax-year')?.value, 10) || currentDate.getFullYear();
    card.innerHTML = `
        <div style="display:flex; align-items:flex-start; gap:10px; margin-bottom:10px;">
            <span class="drawer-icon-box" style="width:34px; height:34px; border-radius:10px; background:var(--accent-soft); color:var(--accent); flex-shrink:0;">
                ${renderIcon('lock', 16)}
            </span>
            <div style="min-width:0; flex:1;">
                <strong style="display:block; font-size:13px; color:var(--text-main);">Paquete para el Contador (${activeYear})</strong>
                <small style="display:block; font-size:11px; color:var(--text-muted); line-height:1.4;">
                    Exporta tus topes DIAN, ingresos/retenciones, total 4x1000 (GMF), consumos de tarjetas y saldos a 31 de diciembre protegido con <b>AES-256-GCM</b>.
                </small>
            </div>
        </div>

        <button type="button" id="btn-export-accountant-csv-enc" class="btn btn-primary" style="width:100%; font-size:12.5px; padding:11px 14px; display:flex; align-items:center; justify-content:center; gap:7px; margin-bottom:8px;">
            ${renderIcon('lock', 15)}
            <span>Exportar Cifrado ${activeYear} (.lumen-csv)</span>
        </button>

        <div style="display:grid; grid-template-columns:1fr 1fr; gap:7px;">
            <button type="button" id="btn-unlock-accountant-csv" class="btn btn-secondary" style="font-size:11px; font-weight:700; padding:8px 8px; display:flex; align-items:center; justify-content:center; gap:5px;">
                ${renderIcon('archive', 13)}
                <span>Abrir .lumen-csv</span>
            </button>
            <button type="button" id="btn-export-accountant-csv-plain" class="btn btn-secondary" style="font-size:11px; font-weight:700; padding:8px 8px; display:flex; align-items:center; justify-content:center; gap:5px;">
                ${renderIcon('receipt', 13)}
                <span>.CSV sin cifrar</span>
            </button>
        </div>
        <input type="file" id="input-unlock-accountant-csv" class="hidden">

        <small style="display:block; margin-top:8px; font-size:10px; color:var(--text-muted); line-height:1.38;">
            Incluye automáticamente movimientos cerrados de ${activeYear} (incluso si ya los archivaste en IndexedDB).
        </small>
        <div style="margin-top:9px; background:rgba(245, 158, 11, 0.08); border-left:3px solid #f59e0b; padding:8px 10px; border-radius:8px; font-size:10px; color:var(--text-muted); line-height:1.42; display:flex; gap:6px; align-items:flex-start;">
            <svg class="ui-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#f59e0b" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0; margin-top:1px;"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>
            <div><b>AVISO:</b> Esta información es construida de acuerdo con lo registrado en la app. <b>NO</b> reemplaza la realidad económica del usuario ni la información exógena oficial con la que la DIAN u otras entidades validan tu obligación de declarar.</div>
        </div>
    `;

    card.querySelector('#btn-export-accountant-csv-enc')?.addEventListener('click', () => {
        window.exportAccountantDianPackageCsv(activeYear, { encrypted: true });
    });
    card.querySelector('#btn-export-accountant-csv-plain')?.addEventListener('click', () => {
        window.exportAccountantDianPackageCsv(activeYear, { encrypted: false });
    });
    const fileInp = card.querySelector('#input-unlock-accountant-csv');
    card.querySelector('#btn-unlock-accountant-csv')?.addEventListener('click', () => fileInp?.click());
    fileInp?.addEventListener('change', (ev) => {
        const f = ev.target.files?.[0];
        if (f) window.decryptAccountantLumenCsvFile(f);
        ev.target.value = '';
    });
};

const rentaAnchorObsTarget = document.getElementById('renta-proj-details');
if (rentaAnchorObsTarget) {
    new MutationObserver(() => setTimeout(injectAccountantPackageCard, 30)).observe(rentaAnchorObsTarget, { childList: true });
    setTimeout(injectAccountantPackageCard, 120);
}
// ==========================================
// CONTROL DE CICLOS PAGADOS ANTES DE USAR LA APP (TARJETAS Y DEUDAS)
// ==========================================
(function initPreAppSettledControls() {
    const injectFormSwitches = () => {
        // 1. Switch dentro de Nueva Tarjeta (se muestra automáticamente solo si Deuda a la fecha > 0)
        const cardInitGroup = document.getElementById('new-card-initial-quota-group');
        if (cardInitGroup && !document.getElementById('new-card-cycle-already-paid-row')) {
            const row = document.createElement('label');
            row.id = 'new-card-cycle-already-paid-row';
            row.className = 'switch-row';
            row.style.cssText = 'margin-top:10px; margin-bottom:4px;';
            row.innerHTML = `
                <div>
                    <strong>¿Ya pagaste el extracto próximo a vencer?</strong>
                    <small>Actívalo si ya cubriste este corte antes de registrar la tarjeta (no moverá tus cuentas)</small>
                </div>
                <span class="switch"><input type="checkbox" id="new-card-cycle-already-paid"><span class="slider"></span></span>
            `;
            cardInitGroup.appendChild(row);
        }

        // 2. Switch dentro de Nuevo Préstamo / Cupo (visible cuando hay saldo y no es libranza)
        const debtPayrollRow = document.getElementById('new-debt-payroll')?.closest('.switch-row');
        if (debtPayrollRow && !document.getElementById('new-debt-cycle-already-paid-row')) {
            const row = document.createElement('label');
            row.id = 'new-debt-cycle-already-paid-row';
            row.className = 'switch-row hidden';
            row.style.cssText = 'margin-bottom:12px;';
            row.innerHTML = `
                <div>
                    <strong>¿Ya pagaste la cuota de este ciclo?</strong>
                    <small>Actívalo si ya cubriste el próximo vencimiento antes de registrarlo (no moverá tus cuentas)</small>
                </div>
                <span class="switch"><input type="checkbox" id="new-debt-cycle-already-paid"><span class="slider"></span></span>
            `;
            debtPayrollRow.insertAdjacentElement('afterend', row);

            const syncDebtPrePaidVisibility = () => {
                const orig = parseMoneyInput(document.getElementById('new-debt-original')?.value);
                const curr = parseMoneyInput(document.getElementById('new-debt-current')?.value);
                const isLib = !!document.getElementById('new-debt-payroll')?.checked;
                row.classList.toggle('hidden', isLib || (orig <= 0 && curr <= 0));
            };
            ['new-debt-original', 'new-debt-current', 'new-debt-payroll'].forEach(id => {
                document.getElementById(id)?.addEventListener('input', syncDebtPrePaidVisibility);
                document.getElementById(id)?.addEventListener('change', syncDebtPrePaidVisibility);
            });
            document.getElementById('new-debt-form')?.addEventListener('reset', () => {
                setTimeout(() => row.classList.add('hidden'), 10);
            });
        }
    };

    const renderDebtPrePaidDetailButton = (accountId) => {
        const payDebtBtn = document.getElementById('open-pay-installment-btn');
        if (!payDebtBtn || typeof toggleLiabilityCycleSettled !== 'function') return;

        let slot = document.getElementById('debt-prepaid-cycle-slot');
        if (!slot) {
            slot = document.createElement('div');
            slot.id = 'debt-prepaid-cycle-slot';
            slot.style.marginTop = '8px';
            payDebtBtn.insertAdjacentElement('afterend', slot);
        }

        const acc = (financeData.customAccounts || []).find(a => String(a.id) === String(accountId));
        const bal = acc ? round2(currentBalances[acc.id] || 0) : 0;
        if (!acc || acc.category !== 'debt' || acc.payrollDeduction || bal <= 0.01) {
            slot.innerHTML = '';
            slot.classList.add('hidden');
            return;
        }

        const refStart = new Date(currentDate.getFullYear(), currentDate.getMonth(), currentDate.getDate(), 0, 0, 0);
        let settledDateFound = null;

        if (acc.paymentDay) {
            for (let mOff = -1; mOff <= 1; mOff++) {
                const probe = new Date(refStart.getFullYear(), refStart.getMonth() + mOff, 1);
                const maxD = new Date(probe.getFullYear(), probe.getMonth() + 1, 0).getDate();
                const cand = new Date(probe.getFullYear(), probe.getMonth(), Math.min(acc.paymentDay, maxD), 12, 0, 0);
                const diff = Math.round((new Date(cand.getFullYear(), cand.getMonth(), cand.getDate()).getTime() - refStart.getTime()) / 86400000);
                if (diff >= -15 && diff <= 25 && isLiabilityCycleMarkedSettled(acc, cand)) {
                    settledDateFound = cand;
                    break;
                }
            }
        } else if (isLiabilityCycleMarkedSettled(acc, currentDate)) {
            settledDateFound = currentDate;
        }

        if (settledDateFound) {
            const lbl = acc.paymentDay
                ? settledDateFound.toLocaleDateString('es-CO', { day: 'numeric', month: 'long' })
                : 'este mes';
            slot.classList.remove('hidden');
            slot.innerHTML = `
                <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; padding:8px 11px; border-radius:12px; background:var(--positive-bg); border:1px solid color-mix(in srgb, var(--positive) 30%, transparent); font-size:11.5px;">
                    <span style="color:var(--positive); font-weight:700;">✓ Cuota de ${lbl} marcada como ya pagada</span>
                    <button type="button" id="btn-undo-debt-prepaid" class="mini-action-btn" style="padding:3px 9px; font-size:10.5px; color:var(--text-main);">Deshacer</button>
                </div>
            `;
            slot.querySelector('#btn-undo-debt-prepaid')?.addEventListener('click', () => {
                toggleLiabilityCycleSettled(acc.id, settledDateFound, false);
                updateDashboard();
                openAccountDetail(acc.id, lastAccountViewOrigin);
            });
            return;
        }

        let targetUnpaidDate = null;
        let targetLabel = 'este mes';

        if (acc.paymentDay && typeof getNextUnpaidLiabilityCycle === 'function') {
            const nextDue = getNextUnpaidLiabilityCycle(acc, bal, currentDate, 5);
            if (nextDue && nextDue.diffDays <= 22 && nextDue.amount > 0) {
                targetUnpaidDate = nextDue.dueDate;
                targetLabel = `el ${nextDue.dueDate.toLocaleDateString('es-CO', { day: 'numeric', month: 'long' })}`;
            }
        } else if (!acc.paymentDay) {
            const mId = getMonthId(currentDate);
            const hasTransfer = (financeData.transactions || []).some(
                t => !t.isDeleted && isTxClosed(t) && t.paymentMode !== 'extraordinary' && getTxMonthId(t) === mId && t.type === 'transfer' && t.toAccount === acc.id
            );
            if (!hasTransfer) targetUnpaidDate = currentDate;
        }

        if (targetUnpaidDate) {
            slot.classList.remove('hidden');
            slot.innerHTML = `
                <button type="button" id="btn-mark-debt-prepaid" class="btn btn-secondary" style="width:100%; padding:8px 12px; border-radius:12px; font-size:11.5px; font-weight:700; border-style:dashed; color:var(--text-muted); display:flex; align-items:center; justify-content:center; gap:6px;">
                    <span style="color:var(--positive); font-weight:900;">✓</span>
                    <span>Ya pagué la cuota de <b style="color:var(--text-main);">${targetLabel}</b> (sin mover cuentas)</span>
                </button>
            `;
            slot.querySelector('#btn-mark-debt-prepaid')?.addEventListener('click', () => {
                toggleLiabilityCycleSettled(acc.id, targetUnpaidDate, true);
                updateDashboard();
                openAccountDetail(acc.id, lastAccountViewOrigin);
            });
        } else {
            slot.innerHTML = '';
            slot.classList.add('hidden');
        }
    };

    injectFormSwitches();
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', injectFormSwitches);
    }

    const baseOpenAccountDetail = window.openAccountDetail;
    if (typeof baseOpenAccountDetail === 'function') {
        window.openAccountDetail = function (accountId, originType = 'home') {
            baseOpenAccountDetail(accountId, originType);
            renderDebtPrePaidDetailButton(accountId);
        };
    }
})();
// ============================================================
// MÓDULO 18: CUOTA DE MANEJO EN CUENTAS DE AHORROS Y CORRIENTE
// ============================================================
(() => {
    const syncNewMgmtUI = () => {
        const subType = document.getElementById('new-account-subtype')?.value || 'savings';
        const eligible = subType === 'savings' || subType === 'checking';
        const box = document.getElementById('new-account-mgmt-box');
        const chk = document.getElementById('new-account-has-mgmt-fee');
        const fields = document.getElementById('new-account-mgmt-fields');
        const wType = document.getElementById('new-account-mgmt-waiver-type')?.value || 'none';
        const wBox = document.getElementById('new-account-mgmt-waiver-box');
        const wLbl = document.getElementById('new-account-mgmt-waiver-label');

        if (!box) return;
        box.classList.toggle('hidden', !eligible);
        if (!eligible && chk) chk.checked = false;
        if (fields) fields.classList.toggle('hidden', !(eligible && chk?.checked));
        if (wBox) wBox.classList.toggle('hidden', wType === 'none');
        if (wLbl) {
            wLbl.textContent = wType === 'monthly_income'
                ? 'Ingresos mínimos al mes para exonerar ($)'
                : 'Saldo mínimo en cuenta para exonerar ($)';
        }
    };

    document.getElementById('new-account-subtype')?.addEventListener('change', syncNewMgmtUI);
    document.getElementById('new-account-has-mgmt-fee')?.addEventListener('change', syncNewMgmtUI);
    document.getElementById('new-account-mgmt-waiver-type')?.addEventListener('change', syncNewMgmtUI);
    document.getElementById('add-account-form')?.addEventListener('reset', () => setTimeout(syncNewMgmtUI, 20));
    syncNewMgmtUI();

    const syncEditWaiverUI = () => {
        const wType = document.getElementById('edit-account-mgmt-waiver-type')?.value || 'none';
        const wBox = document.getElementById('edit-account-mgmt-waiver-box');
        const wLbl = document.getElementById('edit-account-mgmt-waiver-label');
        if (wBox) wBox.classList.toggle('hidden', wType === 'none');
        if (wLbl) {
            wLbl.textContent = wType === 'monthly_income'
                ? 'Ingresos mínimos al mes para exonerar ($)'
                : 'Saldo mínimo en cuenta para exonerar ($)';
        }
    };

    const renderEditMgmtStatusBox = (acc) => {
        const statusBox = document.getElementById('edit-account-mgmt-status-box');
        if (!statusBox || !acc || typeof evaluateAccountMgmtFeeCycle !== 'function') return;
        if (!acc.hasMgmtFee || round2(acc.mgmtFee || 0) <= 0) {
            statusBox.innerHTML = '';
            return;
        }

        const mId = getMonthId(currentDate);
        const st = evaluateAccountMgmtFeeCycle(acc, mId, null, currentDate);
        const esc = window.escapeHtml || ((s) => String(s ?? ''));
        let toneBg = 'var(--accent-soft)';
        let toneColor = 'var(--accent)';
        let title = `Pendiente • Día ${st.day}`;
        let desc = st.autoCharge
            ? (st.insufficientFunds
                ? `Saldo insuficiente (${formatMoney(st.balance)}) para el cobro automático de ${formatMoney(st.amount)}.`
                : `Se descontará automáticamente (${formatMoney(st.amount)}) el día ${st.day}.`)
            : `Cobro manual programado (${formatMoney(st.amount)}) para el día ${st.day}.`;

        if (st.status === 'charged') {
            toneBg = 'var(--positive-bg)'; toneColor = 'var(--positive)';
            title = 'Cobrada este mes';
            desc = `Ya se descontó ${formatMoney(st.amount)} en ${mId}.`;
        } else if (st.status === 'waived') {
            toneBg = 'var(--positive-bg)'; toneColor = 'var(--positive)';
            title = 'Exonerada este mes';
            desc = esc(st.waiverLabel || 'Cumple condición de exoneración.');
        } else if (st.status === 'skipped') {
            toneBg = 'rgba(245, 158, 11, 0.14)'; toneColor = '#d97706';
            title = 'Omitida este mes';
            desc = 'No se descontará ni restará en Libre Seguro este mes.';
        } else if (st.status === 'in_trash') {
            toneBg = 'rgba(245, 158, 11, 0.14)'; toneColor = '#d97706';
            title = 'En Papelera este mes';
            desc = 'El cobro de este mes fue enviado a la Papelera y no se repetirá solo.';
        } else if (st.insufficientFunds) {
            toneBg = 'var(--negative-bg)'; toneColor = 'var(--negative)';
            title = 'Saldo insuficiente';
        }

        const actionsHtml = st.status === 'charged'
            ? ''
            : `
                <div style="display:flex; flex-wrap:wrap; gap:6px; margin-top:8px;">
                    <button type="button" id="btn-charge-acc-mgmt-now" class="mini-action-btn" style="flex:1; justify-content:center; font-weight:800; color:var(--accent);">Cobrar este mes</button>
                    <button type="button" id="btn-toggle-skip-acc-mgmt" class="mini-action-btn" style="flex:1; justify-content:center;">${st.status === 'skipped' ? 'Reactivar mes' : 'Omitir mes'}</button>
                    <button type="button" id="btn-ics-acc-mgmt" class="mini-action-btn" style="justify-content:center;" title="Alarma de calendario">Alarma (.ics)</button>
                </div>
            `;

        statusBox.innerHTML = `
            <div style="padding:9px 11px; border-radius:11px; background:${toneBg}; font-size:11.5px; line-height:1.4;">
                <strong style="display:block; color:${toneColor}; margin-bottom:2px;">${title}</strong>
                <span style="color:var(--text-main);">${desc}</span>
                ${actionsHtml}
            </div>
        `;

        statusBox.querySelector('#btn-charge-acc-mgmt-now')?.addEventListener('click', () => {
            const res = chargeAccountMgmtFee(acc.id, mId, { allowManualOverride: true });
            if (res.ok) {
                updateDashboard();
                openAccountDetail(acc.id, lastAccountViewOrigin);
            }
        });

        statusBox.querySelector('#btn-toggle-skip-acc-mgmt')?.addEventListener('click', () => {
            if (!Array.isArray(acc.mgmtFeeSkippedMonths)) acc.mgmtFeeSkippedMonths = [];
            if (acc.mgmtFeeSkippedMonths.includes(mId)) {
                acc.mgmtFeeSkippedMonths = acc.mgmtFeeSkippedMonths.filter(x => x !== mId);
            } else {
                acc.mgmtFeeSkippedMonths.push(mId);
            }
            localStorage.setItem('myFinances', JSON.stringify(financeData));
            updateDashboard();
            renderEditMgmtStatusBox(acc);
        });

        statusBox.querySelector('#btn-ics-acc-mgmt')?.addEventListener('click', () => {
            if (typeof downloadIcsEvent === 'function' && st.dueDate) {
                const cleanAcc = stripLeadingEmoji(acc.name);
                downloadIcsEvent(`Cuota de manejo ${cleanAcc}`, `Cobro estimado: ${formatMoney(st.amount)} en tu cuenta ${cleanAcc}.`, st.dueDate);
            }
        });
    };

    const populateEditAccountMgmtUI = () => {
        const section = document.getElementById('edit-account-mgmt-section');
        const accId = document.getElementById('reconcile-account-id')?.value || '';
        if (!section || !accId || typeof financeData === 'undefined') return;

        const acc = (financeData.customAccounts || []).find(a => String(a.id) === String(accId));
        const subType = document.getElementById('edit-account-subtype')?.value || acc?.accountSubType || 'savings';
        const eligible = acc && acc.category === 'asset' && acc.id !== 'Efectivo' && !String(acc.id).startsWith('CxC_') && (subType === 'savings' || subType === 'checking');

        section.classList.toggle('hidden', !eligible);
        if (!eligible) return;

        const chk = document.getElementById('edit-account-has-mgmt-fee');
        const fields = document.getElementById('edit-account-mgmt-fields');
        const feeInp = document.getElementById('edit-account-mgmt-fee');
        const dayInp = document.getElementById('edit-account-mgmt-day');
        const autoChk = document.getElementById('edit-account-mgmt-auto');
        const wTypeSel = document.getElementById('edit-account-mgmt-waiver-type');
        const wAmtInp = document.getElementById('edit-account-mgmt-waiver-amt');

        if (chk) chk.checked = !!acc.hasMgmtFee;
        if (fields) fields.classList.toggle('hidden', !acc.hasMgmtFee);
        if (feeInp) feeInp.value = acc.mgmtFee > 0 ? formatNumberInput(acc.mgmtFee) : '';
        if (dayInp) dayInp.value = acc.mgmtFeeDay || 15;
        if (autoChk) autoChk.checked = acc.mgmtFeeAutoCharge !== false;
        if (wTypeSel) wTypeSel.value = acc.mgmtFeeWaiverType || 'none';
        if (wAmtInp) wAmtInp.value = acc.mgmtFeeWaiverAmount > 0 ? formatNumberInput(acc.mgmtFeeWaiverAmount) : '';

        syncEditWaiverUI();
        renderEditMgmtStatusBox(acc);
    };

    document.getElementById('edit-account-has-mgmt-fee')?.addEventListener('change', (e) => {
        const fields = document.getElementById('edit-account-mgmt-fields');
        if (fields) fields.classList.toggle('hidden', !e.target.checked);
        if (!e.target.checked) {
            const accId = document.getElementById('reconcile-account-id')?.value || '';
            const acc = (financeData.customAccounts || []).find(a => String(a.id) === String(accId));
            if (acc && acc.hasMgmtFee) {
                acc.hasMgmtFee = false;
                localStorage.setItem('myFinances', JSON.stringify(financeData));
                hasUnsavedChanges = false;
                updateDashboard();
            }
        }
    });

    document.getElementById('edit-account-mgmt-waiver-type')?.addEventListener('change', syncEditWaiverUI);

    document.getElementById('edit-account-subtype')?.addEventListener('change', (e) => {
        const sub = e.target.value;
        const accId = document.getElementById('reconcile-account-id')?.value || '';
        const acc = (financeData.customAccounts || []).find(a => String(a.id) === String(accId));
        if (acc && sub !== 'savings' && sub !== 'checking' && acc.hasMgmtFee) {
            acc.hasMgmtFee = false;
            localStorage.setItem('myFinances', JSON.stringify(financeData));
        }
        setTimeout(populateEditAccountMgmtUI, 20);
    });

    document.getElementById('btn-save-account-mgmt-fee')?.addEventListener('click', () => {
        const accId = document.getElementById('reconcile-account-id')?.value || '';
        const acc = (financeData.customAccounts || []).find(a => String(a.id) === String(accId));
        if (!acc) return;

        const enabled = !!document.getElementById('edit-account-has-mgmt-fee')?.checked;
        const feeVal = parseMoneyInput(document.getElementById('edit-account-mgmt-fee')?.value);
        const dayVal = Math.max(1, Math.min(31, parseInt(document.getElementById('edit-account-mgmt-day')?.value, 10) || 15));
        const autoVal = !!document.getElementById('edit-account-mgmt-auto')?.checked;
        const wType = document.getElementById('edit-account-mgmt-waiver-type')?.value || 'none';
        const wAmt = wType !== 'none' ? parseMoneyInput(document.getElementById('edit-account-mgmt-waiver-amt')?.value) : 0;

        if (enabled && feeVal <= 0) {
            alert('Ingresa un valor mayor a $0 para la cuota de manejo.');
            return;
        }

        const wasEnabled = !!acc.hasMgmtFee;
        acc.hasMgmtFee = enabled;
        acc.mgmtFee = enabled ? feeVal : 0;
        acc.mgmtFeeDay = dayVal;
        acc.mgmtFeeAutoCharge = autoVal;
        acc.mgmtFeeWaiverType = enabled ? wType : 'none';
        acc.mgmtFeeWaiverAmount = enabled ? wAmt : 0;
        if (enabled && (!wasEnabled || !acc.mgmtFeeConfiguredAt)) {
            acc.mgmtFeeConfiguredAt = new Date().toLocaleDateString('en-CA');
        }
        if (!Array.isArray(acc.mgmtFeeSkippedMonths)) acc.mgmtFeeSkippedMonths = [];

        localStorage.setItem('myFinances', JSON.stringify(financeData));
        hasUnsavedChanges = false;
        updateDashboard();
        renderEditMgmtStatusBox(acc);

        const toast = document.createElement('div');
        toast.className = 'sw-toast';
        toast.textContent = enabled ? 'Cuota de manejo guardada' : 'Cuota de manejo desactivada';
        document.body.appendChild(toast);
        setTimeout(() => toast.remove(), 2200);
    });

    // Sincronizar automáticamente cuando se abre el detalle de cualquier cuenta
    const detailView = document.getElementById('account-detail-view');
    if (detailView) {
        new MutationObserver(() => {
            if (!detailView.classList.contains('hidden')) {
                setTimeout(populateEditAccountMgmtUI, 25);
            }
        }).observe(detailView, { attributes: true, attributeFilter: ['class'] });
    }

    // Inyectar píldora visual sutil en la lista de Cuentas (#accounts-summary-list)
    const decorateAccountMgmtBadges = () => {
        const listEl = document.getElementById('accounts-summary-list');
        if (!listEl || typeof evaluateAccountMgmtFeeCycle !== 'function') return;
        const mId = getMonthId(currentDate);
        listEl.querySelectorAll('.acc-list-item[data-lumen-args]').forEach(row => {
            if (row.querySelector('.acc-mgmt-pill')) return;
            let accId = '';
            try { accId = JSON.parse(row.getAttribute('data-lumen-args') || '[]')[0] || ''; } catch { return; }
            const acc = (financeData.customAccounts || []).find(a => String(a.id) === String(accId));
            if (!acc || !isAccountMgmtFeeEligible(acc) || !acc.hasMgmtFee) return;
            const st = evaluateAccountMgmtFeeCycle(acc, mId, null, currentDate);
            if (!st.enabled) return;

            const nameBox = row.querySelector('.acc-list-name > div') || row.querySelector('.acc-list-name');
            if (!nameBox) return;
            const pill = document.createElement('small');
            pill.className = 'acc-mgmt-pill';
            pill.style.cssText = 'display:block; font-size:10px; font-weight:700; margin-top:2px; color:' +
                (st.status === 'waived' || st.status === 'charged' ? 'var(--positive)' : 'var(--text-muted)') + ';';
            pill.textContent = st.status === 'waived'
                ? 'Manejo exonerado este mes'
                : (st.status === 'charged'
                    ? `Manejo cobrado (${formatCompact(st.amount)})`
                    : `Manejo: ${formatCompact(st.amount)} • Día ${st.day}`);
            nameBox.appendChild(pill);
        });
    };

    const accListEl = document.getElementById('accounts-summary-list');
    if (accListEl) {
        new MutationObserver(decorateAccountMgmtBadges).observe(accListEl, { childList: true });
    }
})();